
const LOGO=`<svg width="34" height="34" viewBox="0 0 40 40" aria-hidden="true"><path fill="#174D3C" d="M8 4h24a6 6 0 016 6v17a6 6 0 01-6 6H21l-9 6v-6H8a6 6 0 01-6-6V10a6 6 0 016-6z"/><path fill="#F7F4EB" fill-rule="evenodd" d="M14 10h8a5.5 5.5 0 010 11h-3v5h-5zM19 14v3h3a1.5 1.5 0 000-3z"/><circle cx="34" cy="8" r="4" fill="#EF795F"/></svg>`;
// ---- CONTEÚDO: "título#nota#it|pt;it|pt" ----
const ITALIAN_COURSE=[
["Primeiros contatos","Cumprimentos, despedidas e cortesia",[
`Cumprimentos#"Ciao" serve para oi e tchau, só com amigos. "Buongiorno" usa-se até o início da tarde. Pronúncia: "ci" soa "tchi" (ciao = tchau).#Ciao|Oi / tchau;Buongiorno|Bom dia;Buonasera|Boa tarde / boa noite;Buonanotte|Boa noite (ao dormir);Come stai?|Como você está?;Sto bene, grazie|Estou bem, obrigado(a)`,
`Despedidas#"Arrivederci" é a despedida padrão. "A presto" = até breve. Cultura: na Itália é comum desejar "Buona giornata" ao sair de lojas.#Arrivederci|Até logo;A presto|Até breve;A domani|Até amanhã;Ci vediamo|A gente se vê;Buona giornata|Tenha um bom dia;Buon viaggio|Boa viagem`,
`Cortesia#"Prego" significa "de nada", mas também "fique à vontade". "Scusi" é a forma educada; "scusa" é informal.#Per favore|Por favor;Grazie mille|Muito obrigado;Prego|De nada;Scusi|Com licença;Mi dispiace|Sinto muito;Non c'è problema|Não tem problema`]],
["Apresentações","Nome, origem, nacionalidade e pronomes",[
`Nome#"Mi chiamo Luca" = literalmente "eu me chamo Luca". É a forma natural de se apresentar. "ti" é informal; "si" é formal.#Mi chiamo Luca|Eu me chamo Luca;Come ti chiami?|Como você se chama?;Come si chiama?|Como o senhor se chama?;Piacere|Prazer;Molto piacere|Muito prazer;Sono Marta|Eu sou a Marta`,
`Origem#Nacionalidades terminam em -o (masculino) ou -a (feminino). "Di" indica a cidade; "dal" o país masculino.#Sono brasiliano|Sou brasileiro;Sono brasiliana|Sou brasileira;Di dove sei?|De onde você é?;Sono di Recife|Sou de Recife;Vengo dal Brasile|Venho do Brasil;Sei italiano?|Você é italiano?`,
`Pronomes#Em italiano o pronome costuma ser omitido: "Sono stanco". "Lei" também é a forma de respeito ("o senhor/a senhora").#Io sono|Eu sou;Tu sei|Tu és / você é;Lui è|Ele é;Lei è|Ela é;Noi siamo|Nós somos;Loro sono|Eles são`]],
["Frases essenciais","Essere e avere em contexto",[
`Essere#Essere = ser/estar. Atenção: "è" (verbo) ≠ "e" (conjunção "e"). Pronúncia: "è" tem acento aberto.#Sono stanco|Estou cansado;Sei di Roma|Você é de Roma;Lei è la mia amica|Ela é minha amiga;Siamo a casa|Estamos em casa;Siete qui|Vocês estão aqui;Sono felice|Estou feliz`,
`Avere#Avere = ter. O "h" é mudo: ho, hai, ha, hanno. Em italiano diz-se "tenho fome" (ho fame), como em português.#Ho una sorella|Tenho uma irmã;Hai fame?|Você está com fome?;Ha un cane|Ele tem um cachorro;Abbiamo tempo|Temos tempo;Avete sete?|Vocês estão com sede?;Hanno una casa|Eles têm uma casa`,
`Em contexto#Atenção: "caldo" é calor, não "caldo" de comida. Estados físicos usam avere: ho sonno, ho caldo, ho freddo.#Ho sonno|Estou com sono;Ho caldo|Estou com calor;Non ho freddo|Não estou com frio;Dove sei?|Onde você está?;Sono a Roma|Estou em Roma;Ho bisogno di aiuto|Preciso de ajuda`]],
["Pessoas e família","Vocabulário, gênero e artigos básicos",[
`Família#Substantivos femininos costumam terminar em -a, masculinos em -o. Artigo masculino: il; feminino: la.#la madre|a mãe;il padre|o pai;il fratello|o irmão;la sorella|a irmã;il nonno|o avô;la nonna|a avó`,
`Pessoas#Antes de vogal, o artigo vira l': l'amico, l'amica, l'uomo.#l'amico|o amigo;l'amica|a amiga;il bambino|o menino;la bambina|a menina;l'uomo|o homem;la donna|a mulher`,
`Artigos#Indefinidos: un/una (um/uma). Plurais: i (masc.) e le (fem.). Falso cognato: "parenti" = parentes, não pais.#un libro|um livro;una casa|uma casa;il ragazzo|o rapaz;la ragazza|a moça;i figli|os filhos;le sorelle|as irmãs`]],
["No café","Comidas, bebidas e pedidos simples",[
`Bebidas#Cultura: "un caffè" na Itália é um expresso pequeno. Cappuccino costuma ser tomado só de manhã.#un caffè|um café;un'acqua|uma água;un tè|um chá;un succo|um suco;il latte|o leite;una birra|uma cerveja`,
`Comidas#"Cornetto" é o croissant italiano. "Gelato" é sorvete.#il pane|o pão;il cornetto|o croissant;la pizza|a pizza;il formaggio|o queijo;la torta|o bolo;il gelato|o sorvete`,
`Pedidos#"Vorrei" (eu gostaria) é a forma educada de pedir. Pronúncia: "ggi" em "formaggio" soa como "dj"; "gn", em "lasagna", soa como "nh".#Vorrei un caffè|Eu queria um café;Un cappuccino, per favore|Um cappuccino, por favor;Quanto costa?|Quanto custa?;Il conto, per favore|A conta, por favor;Un tavolo per due|Uma mesa para dois;Posso pagare con la carta?|Posso pagar com cartão?`]],
["Vida cotidiana","Números, horários e verbos regulares",[
`Números#Pronúncia: "tre" com r vibrante; "cinque" soa "tchínkue".#uno|um;due|dois;tre|três;quattro|quatro;cinque|cinco;dieci|dez`,
`Horários#Usa-se o artigo plural: "Sono le tre", mas "È mezzogiorno" e "È mezzanotte" no singular.#Che ore sono?|Que horas são?;Sono le tre|São três horas;È mezzogiorno|É meio-dia;È mezzanotte|É meia-noite;A che ora?|A que horas?;Alle otto|Às oito`,
`Verbos#Verbos em -are: eu termina em -o (parlare → parlo). Falso cognato: "abito" = moro, não "hábito".#Parlo italiano|Falo italiano;Mangio la pizza|Como pizza;Bevo un caffè|Bebo um café;Lavoro a Recife|Trabalho em Recife;Abito qui|Moro aqui;Studio ogni giorno|Estudo todo dia`]]
].map((u,ui)=>({t:u[0],d:u[1],l:u[2].map((s,li)=>{const[t,n,w]=s.split('#');return{t,n,k:ui+'-'+li,w:w.split(';').map((x,i)=>{const[it,pt]=x.split('|');return{k:ui+'-'+li+'-'+i,it,pt,c:u[0]}})}})}));
let course='it',account=null,guest=false,authReady=false,authBusy=false,authMode='login',authError='',syncState='local',syncBusy=false,conflict=null;
const COURSES={it:enrichFoundation(ITALIAN_COURSE,'it').concat(buildExpansion('it')),en:enrichFoundation(ENGLISH_COURSE,'en').concat(buildExpansion('en'))};
let U=COURSES.it,V=U.flatMap(u=>u.l.flatMap(l=>l.w)),VK=Object.fromEntries([...V,...VOCABULARY[course]].map(x=>[x.k,x]));
const LANGUAGE={it:{name:'Italiano',target:'italiano',voice:'it-IT',greet:['Buongiorno','Buon pomeriggio','Buonasera'],hello:'Ciao.',bye:'A PRESTO',motto:'Il tuo italiano.'},en:{name:'Inglês',target:'inglês',voice:'en-US',greet:['Good morning','Good afternoon','Good evening'],hello:'Hello.',bye:'SEE YOU SOON',motto:'Your English journey.'}};
const language=()=>LANGUAGE[course];
function setCourse(c){course=c;U=COURSES[c];V=U.flatMap(u=>u.l.flatMap(l=>l.w));VK=Object.fromEntries([...V,...VOCABULARY[course]].map(x=>[x.k,x]));resetLexFilters();}
// ---- ESTADO + PERSISTÊNCIA (IndexedDB) ----
const DEF=()=>({v:1,p:{name:'',lvl:0,goal:'viagens',min:10,theme:'dark',snd:1,rm:0,on:0},xp:0,days:{},done:{},srs:{},fav:{},acc:{},sess:null,last:null});
let S=DEF();
const db=new Promise(r=>{try{const q=indexedDB.open('parlo',1);q.onupgradeneeded=()=>q.result.createObjectStore('kv');q.onsuccess=()=>r(q.result);q.onerror=()=>r(null)}catch(e){r(null)}});
async function localGet(key){const d=await db;if(!d)return;return new Promise(resolve=>{const q=d.transaction('kv').objectStore('kv').get(key);q.onsuccess=()=>resolve(q.result);q.onerror=()=>resolve()})}
async function localPut(key,value){const d=await db;if(!d)return;return new Promise((resolve,reject)=>{const tx=d.transaction('kv','readwrite');tx.objectStore('kv').put(value,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
const owner=()=>account?.id||'guest';
const stateKey=(id,lang)=>'state:'+id+':'+lang;
let records={};let saveTimer;
async function save(){
 const id=owner(),lang=course,key=stateKey(id,lang),state=structuredClone(S),old=records[key]||{revision:0};
 const record={...old,state,dirty:true,localVersion:(old.localVersion||0)+1};records[key]=record;
 try{await localPut(key,record)}catch{syncState='error'}
 if(account){syncState=conflict?'conflict':'pending';clearTimeout(saveTimer);saveTimer=setTimeout(()=>syncProgress(),800)}
}
// ---- CORREÇÃO ----
const norm=s=>s.toLowerCase().replace(/[.,!?;:"¿¡]/g,'').replace(/[’‘]/g,"'").replace(/\s+/g,' ').trim();
const flat=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'');
function grade(a,exp){const x=norm(a),y=norm(exp);if(x===y)return{ok:1};if(flat(x)===flat(y))return{ok:0,m:'Atenção aos acentos: eles mudam o sentido (ex.: "è" = é, verbo; "e" = e, conjunção).'};return{ok:0}}
// ---- REVISÃO ESPAÇADA (regras fixas, não é IA) ----
// Acertos seguidos b: próximo intervalo = [1,3,7,14,30] dias[b-1]. Erro: b=0, volta em 10 min.
const IV=[1,3,7,14,30],DAY=864e5;
function upd(k,ok){const e=S.srs[k]||{b:0};e.b=ok?Math.min(e.b+1,5):0;e.due=Date.now()+(ok?IV[e.b-1]*DAY:6e5);S.srs[k]=e}
const due=()=>Object.keys(S.srs).filter(k=>S.srs[k].due<=Date.now());
// ---- ÁUDIO ----
const hasV=()=>'speechSynthesis' in window&&speechSynthesis.getVoices().some(v=>v.lang.toLowerCase().startsWith(language().voice.slice(0,2)));
const aud=()=>S.p.snd&&hasV();
function say(t,slow){if(!aud())return;const u=new SpeechSynthesisUtterance(t);u.lang=language().voice;u.voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(language().voice.slice(0,2)));u.rate=slow?.55:.95;speechSynthesis.cancel();speechSynthesis.speak(u)}
if('speechSynthesis' in window)speechSynthesis.onvoiceschanged=()=>{if(document.activeElement?.tagName!=='INPUT'&&!recognition)render()};
// ---- UTIL ----
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const shuf=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a};
const td=()=>new Date().toLocaleDateString('sv');
function streak(){let d=new Date(),n=0;if(!S.days[td()])d.setDate(d.getDate()-1);while(S.days[d.toLocaleDateString('sv')]){n++;d.setDate(d.getDate()-1)}return n}
const secs=()=>(S.days[td()]||{s:0}).s;
const nextL=()=>{for(const u of U)for(const l of u.l)if(!S.done[l.k])return[u,l];return[U[0],U[0].l[0]]};
const opts=(x,f)=>shuf([x,...shuf(V.filter(y=>y.k!==x.k&&y[f]!==x[f])).slice(0,3)]).map(y=>y[f]);
// ---- EXERCÍCIOS ----
function mkEx(x,kind){
 const words=x.it.split(' '),multi=words.length>1;
 if(kind==='match'){const g=[x,...shuf(V.filter(y=>y.c===x.c&&y.k!==x.k)).slice(0,3)];return{t:'match',k:x.k,q:'Associe cada item ao significado',ps:g,a:g.map(y=>y.it+' = '+y.pt).join('; '),r:shuf(g.map(y=>y.pt))}}
 if(kind==='listen'&&aud())return{t:'listen',k:x.k,q:'Ouça e escolha a frase correta',a:x.it,o:opts(x,'it'),x:x.pt};
 if(kind==='order'&&multi){let w=shuf(words),n=0;while(w.join(' ')===x.it&&n++<9)w=shuf(w);return{t:'order',k:x.k,q:'Monte a frase: "'+x.pt+'"',a:x.it,w}}
 if(kind==='cloze'&&multi){const i=words.length-1,c=words.slice();c[i]='____';return{t:'cloze',k:x.k,q:'Complete: '+c.join(' ')+'  ("'+x.pt+'")',a:words[i],o:shuf([words[i],...shuf(V.flatMap(y=>y.it.split(' ')).filter(w=>w!==words[i]&&w.length>2)).slice(0,3)])}}
 if(kind==='type')return{t:'type',k:x.k,q:'Traduza para o '+language().target+': "'+x.pt+'"',a:x.it};
 return{t:'choice',k:x.k,q:'Qual é a tradução de "'+x.it+'"?',a:x.pt,o:opts(x,'pt')}}
const KINDS=['choice','order','type','listen','cloze','match'];
function startLesson(k){
 if(S.sess&&S.sess.lk===k){location.hash='#/lic';return}
 const l=U.flatMap(u=>u.l).find(l=>l.k===k);
 S.sess={lk:k,ex:l.w.map((x,i)=>mkEx(x,KINDS[i%6])),i:0,ok:0,intro:0,sec:0,t:Date.now()};save();location.hash='#/lic'}
function startRev(){const ks=due().slice(0,10);if(!ks.length)return;
 S.sess={lk:'rev',ex:ks.map((k,i)=>mkEx(VK[k],i%2?'type':'choice')),i:0,ok:0,intro:1,sec:0,t:Date.now()};save();location.hash='#/lic'}
let st={};
function finish(){const s=S.sess,sec=s.sec,xp=Math.min(200,s.ok*10),d=td();
 if(s.pl){let su=U.findIndex((_,i)=>((s.pu&&s.pu[i])||0)<2);if(su<0)su=U.length-1;S.last={pl:1,ok:s.ok,n:s.ex.length,su};S.sess=null;save();location.hash='#/fim';return}
 const e=S.days[d]||{xp:0,s:0};e.xp+=xp;e.s+=sec;S.days[d]=e;S.xp+=xp;
 if(s.lk!=='rev')S.done[s.lk]=(S.done[s.lk]||0)+1;
 if(s.builderKey){const data=learningStats();data.builders=data.builders||{};const item=data.builders[s.builderKey]||{completed:0,attempts:0,correct:0,last:0};item.completed++;item.attempts+=s.ex.length;item.correct+=s.ok;item.last=Date.now();data.builders[s.builderKey]=item}
 S.last={lk:s.lk,ok:s.ok,n:s.ex.length,xp,sec,...(s.builderKey?{builderKey:s.builderKey}:{}),...(s.lessonMode?{lessonKey:s.lessonKey,lessonMode:s.lessonMode,missedKeys:s.missedKeys||[]}: {})};S.sess=null;save();location.hash='#/fim'}
function check(){if(st.res)return;const s=S.sess,e=s.ex[s.i];let a=e.t==='order'?st.pick.join(' '):e.t==='type'?document.getElementById('ti').value:st.sel,g=e.t==='match'?{ok:st.m.x?0:1}:grade(a,e.a);
 st.res=g;s.feedback=JSON.parse(JSON.stringify(st));if(g.ok)s.ok++;if(s.pl){const u=e.k.split('-')[0];s.pu=s.pu||{};s.pu[u]=(s.pu[u]||0)+g.ok}else upd(e.k,g.ok);const A=S.acc[e.t]||[0,0];A[0]+=g.ok;A[1]++;S.acc[e.t]=A;save();render()}
function next(){const s=S.sess;if(!st.res)return;s.i++;delete s.feedback;st={};if(s.i>=s.ex.length)finish();else{save();render()}}
function lessonView(){const s=S.sess;if(!s){location.hash='#/';return''}
 if(!s.intro){const l=U.flatMap(u=>u.l).find(l=>l.k===s.lk);
  return`<div class="row"><h1>${esc(l.t)}</h1><a class="btn s" href="#/">Sair</a></div><div class="card"><p>${esc(l.n)}</p></div><div class="card">${l.w.map(x=>`<div class="row"><p><b>${esc(x.it)}</b><br><span class="mu">${esc(x.pt)}</span></p><span><button class="btn s" aria-pressed="${!!S.fav[x.k]}" aria-label="Salvar ${esc(x.it)}" onclick="S.fav['${x.k}']=!S.fav['${x.k}'];save();render()">${S.fav[x.k]?'★':'☆'}</button> <button class="btn s" aria-label="Ouvir ${esc(x.it)}" onclick="say(${JSON.stringify(x.it).replace(/"/g,'&quot;')})">Ouvir</button></span></div>`).join('')}${aud()?'':'<p class="mu">Sem voz italiana neste navegador: as atividades usam texto.</p>'}</div><button class="btn w" onclick="S.sess.intro=1;save();render()">Começar</button>`}
 const e=s.ex[s.i],r=st.res,pct=s.i/s.ex.length*100;
 let body='';
 const O=e.o?e.o.map(o=>`<button class="opt" aria-pressed="${st.sel===o}" ${r?'disabled':''} onclick="st.sel=this.dataset.v;render()" data-v="${esc(o)}">${esc(o)}</button>`).join(''):'';
 if(e.t==='listen')body=`<button class="btn s" onclick="say(${JSON.stringify(e.a).replace(/"/g,'&quot;')})">Ouvir</button> <button class="btn s" onclick="say(${JSON.stringify(e.a).replace(/"/g,'&quot;')},1)">Mais devagar</button>${O}`;
 else if(e.t==='order'){st.pick=st.pick||[];body=`<div class="ans" aria-label="Sua frase">${st.pick.map((w,i)=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.splice(${i},1);render()">${esc(w)}</button>`).join('')}</div>`+e.w.map((w,i)=>st.pick.includes(w+'\u0001'+i)?'':`<button class="tile" ${r?'disabled':''} onclick="st.pick.push(this.dataset.w);render()" data-w="${esc(w)}">${esc(w)}</button>`).join('')}
 else if(e.t==='type')body=`<label for="ti">Sua resposta</label><input type="text" id="ti" autocomplete="off" autocapitalize="off" ${r?'disabled':''} onkeydown="if(event.key==='Enter'&&!${!!r})check()" value="${esc(st.ti||'')}" oninput="st.ti=this.value;document.getElementById('vb').disabled=!this.value.trim()">`;
 else if(e.t==='match'){st.m=st.m||{d:[],l:null,x:0};const m=st.m,b=(t,v,s)=>`<button class="tile" style="width:100%;margin:4px 0" ${m.d.includes(v)||r?'disabled':''} ${s?`aria-pressed="${m.l===v}"`:''} onclick="mt(${s?0:1},this.dataset.v)" data-v="${esc(v)}">${m.d.includes(v)?'✓ ':''}${esc(t)}</button>`;body='<div class="g2"><div>'+e.ps.map(p=>b(p.it,p.pt,1)).join('')+'</div><div>'+e.r.map(t=>b(t,t,0)).join('')+'</div></div><p class="mu">Erros: '+m.x+'</p>'}else body=O;
 if(e.t==='order'){const used=[...st.pick];body=`<div class="ans" aria-label="Sua frase">${st.pick.map((w,i)=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.splice(${i},1);render()">${esc(w)}</button>`).join('')}</div>`+e.w.filter(w=>{const i=used.indexOf(w);if(i>-1){used.splice(i,1);return false}return true}).map(w=>`<button class="tile" ${r?'disabled':''} onclick="st.pick.push(this.dataset.w);render()" data-w="${esc(w)}">${esc(w)}</button>`).join('')}
 const ready=e.t==='match'?(st.m&&st.m.d.length===e.ps.length):e.t==='order'?st.pick.length:e.t==='type'?(st.ti||'').trim():st.sel;
 const fb=r?`<div class="fb ${r.ok?'ok':'no'} pop" role="status"><b>${r.ok?'✓ Correto!':'✗ Quase lá'}</b><p>Resposta esperada: <b>${esc(e.a)}</b></p>${r.m?`<p>${esc(r.m)}</p>`:''}<p class="mu">${esc(VK[e.k].it)} = ${esc(VK[e.k].pt)}. Erros voltam na revisão em breve.</p><button class="btn s" aria-pressed="${!!S.fav[e.k]}" onclick="tg('${e.k}')">${S.fav[e.k]?'★ Salvo':'☆ Salvar para ver depois'}</button></div>`:'';
 return`<div class="row"><a class="btn s" href="#/" aria-label="Sair e retomar depois">Sair</a><div class="bar" style="flex:1" role="progressbar" aria-valuenow="${Math.round(pct)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${pct}%"></i></div><span class="mu">${s.i+1}/${s.ex.length}</span></div><h2 style="margin-top:20px">${esc(e.q)}</h2>${body}${fb}${r?`<button class="btn w" onclick="next()">Continuar</button>`:`<button class="btn w" id="vb" ${ready?'':'disabled'} onclick="check()">Verificar</button>`}`}
// ---- TELAS ----
function home(){const[u,l]=nextL(),t=td(),m=Math.floor(secs()/60),pc=Math.min(100,secs()/60/S.p.min*100),nd=due().length,h=new Date().getHours(),wd=V[Math.floor(Date.now()/DAY)%V.length];
 const wk=[...Array(7)].map((_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return(S.days[d.toLocaleDateString('sv')]||{xp:0}).xp}),mx=Math.max(1,...wk);
 const rs=S.sess?U.flatMap(u=>u.l).find(x=>x.k===S.sess.lk):null;
 return`<h1>${language().greet[h<12?0:h<18?1:2]}, ${esc(S.p.name||'estudante')}!</h1>
<div class="card hero"><p class="mu">${S.sess?'Lição em andamento':'Continuar aprendendo'}</p><h2>${esc(rs?rs.t:l.t)}</h2><p class="mu">${esc(u.t)}</p><button class="btn" onclick="startLesson('${rs?S.sess.lk:l.k}')">${S.sess?'Retomar':'Começar lição'}</button></div>
<div class="card"><div class="row"><b>Meta diária</b><span class="mu">${m} / ${S.p.min} min</span></div><div class="bar"><i style="width:${pc}%"></i></div></div>
<div class="g2"><div class="card"><div class="mu">Sequência</div><div class="big">${streak()} dia${streak()==1?'':'s'}</div></div><div class="card"><div class="mu">Revisões</div><div class="big">${nd}</div>${nd?'<a class="btn s" href="#/rev">Revisar</a>':''}</div></div>
<div class="card"><b>Últimos 7 dias (XP)</b><div class="wk" aria-label="XP por dia">${wk.map(x=>`<div style="height:${x/mx*100}%" title="${x} XP"></div>`).join('')}</div><p class="mu">Total: ${S.xp} XP</p></div>
<div class="card"><p class="mu">Palavra do dia</p><div class="row"><div><h2>${esc(wd.it)}</h2><p>${esc(wd.pt)}</p></div><button class="btn s" onclick="say(${JSON.stringify(wd.it).replace(/"/g,'&quot;')})">Ouvir</button></div>${aud()?'':'<p class="mu">Áudio indisponível neste navegador.</p>'}</div>`}
function path(){return`<h1>Trilha</h1><div class="card row"><span class="mu">Não sabe por onde começar?</span><button class="btn s" onclick="startPlace()">Teste de nivelamento</button></div>`+U.map((u,ui)=>`<div class="card"><h2>${ui+1}. ${esc(u.t)}</h2><p class="mu">${esc(u.d)}</p>${u.l.map(l=>{const c=S.done[l.k],p=S.sess&&S.sess.lk===l.k;return`<div class="row" style="margin-top:10px"><div>${esc(l.t)} <span class="st ${c?'d':p?'p':''}">${c?'Concluída ×'+c:p?'Em andamento':'Disponível'}</span></div><button class="btn s" onclick="startLesson('${l.k}')">${c?'Repetir':p?'Retomar':'Iniciar'}</button></div>`}).join('')}</div>`).join('')}
function startRevU(ui){const ks=Object.keys(S.srs).filter(k=>k.startsWith(ui+'-')).sort((a,b)=>S.srs[a].due-S.srs[b].due).slice(0,8);if(!ks.length)return;S.sess={lk:'rev',ex:ks.map((k,i)=>mkEx(VK[k],i%2?'type':'choice')),i:0,ok:0,intro:1,sec:0,t:Date.now()};save();location.hash='#/lic'}
function trail(){const[cu]=nextL(),ci=U.indexOf(cu);
 return`<h1>Trilha de aprendizado</h1><div class="card row"><span class="mu">Não sabe por onde começar?</span><button class="btn s" onclick="startPlace()">Teste de nivelamento</button></div>`+U.map((u,ui)=>{const dn=u.l.filter(l=>S.done[l.k]).length,fut=ui>ci&&!dn,nl=ui===ci?u.l.find(l=>!S.done[l.k]):null,sd=Object.keys(S.srs).filter(k=>k.startsWith(ui+'-')).length;
  return`<section class="un ${fut?'f':''}" aria-label="Unidade ${ui+1}"><div class="rail"><div class="ic" aria-hidden="true">${ui+1}</div>${ui<U.length-1?'<div class="ln"></div>':''}</div><div class="bd"><h2>${esc(u.t)}</h2><p class="mu">${esc(u.d)} · ${dn}/${u.l.length} lições</p>`+u.l.map((l,i)=>{const c=S.done[l.k],p=S.sess&&S.sess.lk===l.k,cur=nl===l;return`<button class="lc ${c?'ok':cur||p?'cur':''}" onclick="startLesson('${l.k}')"><span class="nm" aria-hidden="true">${c?'✓':i+1}</span><span class="tx"><b>${esc(l.t)}</b><span class="sb">${esc(l.w.slice(0,3).map(x=>x.it).join(' · '))}</span></span><span class="mu">${c?'Concluída':p?'Em andamento':cur?'Iniciar ▶':'Disponível'}</span></button>`}).join('')+`<button class="lc rv" ${sd?'':'disabled'} onclick="startRevU(${ui})"><span class="nm" aria-hidden="true">↻</span><span class="tx"><b>Revisão: ${esc(u.t)}</b><span class="sb">${sd?sd+' itens estudados':'Conclua uma lição para liberar'}</span></span></button></div></section>`}).join('')}
function rev(){const n=due().length;return`<h1>Revisão</h1><div class="card"><p>${n?`<b>${n}</b> item(ns) para revisar.`:'Nada para revisar agora. Conclua lições para gerar itens.'}</p><p class="mu">Regra fixa: cada acerto seguido espaça a revisão (1, 3, 7, 14, 30 dias); um erro faz o item voltar em 10 min.</p><button class="btn" ${n?'':'disabled'} onclick="startRev()">Revisar agora</button></div>`}
let q='',cat='';
function vocab(){const L=V.filter(x=>S.srs[x.k]||q||cat).filter(x=>(!cat||(cat==='fav'?S.fav[x.k]:x.c===cat))&&(norm(x.it+' '+x.pt).includes(norm(q))));
 return`<h1>Vocabulário</h1><input type="text" aria-label="Buscar" placeholder="Buscar" value="${esc(q)}" oninput="q=this.value;render();document.querySelector('[aria-label=Buscar]').focus()"><select aria-label="Filtro" onchange="cat=this.value;render()"><option value="">Todas</option><option value="fav" ${cat==='fav'?'selected':''}>Favoritos</option>${U.map(u=>`<option ${cat===u.t?'selected':''}>${esc(u.t)}</option>`).join('')}</select>${L.length?L.map(x=>{const e=S.srs[x.k];return`<div class="card row"><div><b>${esc(x.it)}</b><br>${esc(x.pt)}<br><span class="mu">${esc(x.c)} · ${e?(e.due<=Date.now()?'Revisar':'Em dia'):'Novo'}</span></div><div><button class="btn s" aria-pressed="${!!S.fav[x.k]}" aria-label="Favoritar" onclick="S.fav['${x.k}']=!S.fav['${x.k}'];save();render()">${S.fav[x.k]?'★':'☆'}</button><button class="btn s" aria-label="Ouvir" onclick="say(${JSON.stringify(x.it).replace(/"/g,'&quot;')})">Ouvir</button></div></div>`}).join(''):'<div class="card"><p>Nenhuma palavra estudada ainda. Faça uma lição ou use a busca.</p></div>'}`}
function fim(){const l=S.last;if(!l){location.hash='#/';return''}
 if(l.pl){const u=U[l.su];return`<div class="card hero pop"><h1>Ponto de partida sugerido</h1><p>${l.ok}/${l.n} acertos. Sugerimos começar pela unidade ${l.su+1}: ${esc(u.t)}.</p><p class="mu">É só uma sugestão de por onde começar, não uma certificação de nível.</p></div><button class="btn w" onclick="startLesson('${u.l[0].k}')">Começar por aqui</button>`}const[u,nx]=nextL();return`<div class="card hero pop"><h1>Lição concluída!</h1><p>${l.ok}/${l.n} acertos · +${l.xp} XP · ${Math.max(1,Math.round(l.sec/60))} min</p><p class="mu">Bom trabalho. Pausas curtas ajudam a fixar.</p></div>${due().length?'<a class="btn w" href="#/rev">Revisar erros</a>':''}<p></p><button class="btn s w" onclick="startLesson('${nx.k}')">Próxima: ${esc(nx.t)}</button>`}
function prof(){const p=S.p,ach=[['Primeira lição',Object.keys(S.done).length>0],['3 dias seguidos',streak()>=3],['100 XP',S.xp>=100],['Unidade completa',U.some(u=>u.l.every(l=>S.done[l.k]))]],T={choice:'Escolha',order:'Ordenar',type:'Digitar',listen:'Áudio',cloze:'Lacuna',match:'Associação'};
 return`<div class="row"><h1>Perfil</h1><div class="av" aria-hidden="true">${esc((p.name||'P').slice(0,2).toUpperCase())}</div></div>
<div class="card"><label for="nm">Nome</label><input type="text" id="nm" value="${esc(p.name)}" onchange="S.p.name=this.value;save();render()"><label for="gl">Objetivo</label><select id="gl" onchange="S.p.goal=this.value;save()">${['viagens','conversação','cultura','estudo geral'].map(g=>`<option ${p.goal===g?'selected':''}>${g}</option>`).join('')}</select><label for="mn">Meta diária</label><select id="mn" onchange="S.p.min=+this.value;save();render()">${[5,10,15,20].map(g=>`<option value="${g}" ${p.min===g?'selected':''}>${g} min</option>`).join('')}</select><label for="th">Tema</label><select id="th" onchange="S.p.theme=this.value;save();theme()"><option value="auto">Sistema</option><option value="light" ${p.theme==='light'?'selected':''}>Claro</option><option value="dark" ${p.theme==='dark'?'selected':''}>Escuro</option></select><label><input type="checkbox" ${p.snd?'checked':''} onchange="S.p.snd=+this.checked;save()"> Sons e áudio</label><label><input type="checkbox" ${p.rm?'checked':''} onchange="S.p.rm=+this.checked;save();theme()"> Reduzir animações</label></div>
<div class="card"><h2>Progresso</h2><p>${S.xp} XP · ${Object.keys(S.done).length} lições · ${Object.keys(S.srs).length} palavras estudadas · ${due().length} a revisar</p>${Object.keys(T).map(k=>S.acc[k]?`<p class="mu">${T[k]}: ${S.acc[k][0]}/${S.acc[k][1]} acertos</p>`:'').join('')}<button class="btn s" onclick="startPlace()">Teste de nivelamento</button><h2>Conquistas</h2>${ach.map(a=>`<span class="st ${a[1]?'d':''}">${a[1]?'✓ ':''}${a[0]}</span> `).join('')}</div>
<div class="card"><h2>Dados</h2><p class="mu">Seus dados ficam só neste navegador (IndexedDB). Sem conta: exporte um backup de vez em quando.</p><button class="btn s" onclick="exp()">Exportar JSON</button> <label class="btn s" style="display:inline-block;margin:0">Importar<input type="file" accept=".json" hidden onchange="imp(this.files[0])"></label> <button class="btn s" onclick="if(confirm('Apagar todo o progresso? Isso não pode ser desfeito.')){S=DEF();S.p.on=1;save();location.hash='#/';render()}">Reiniciar</button><p id="msg" class="mu" role="status"></p></div>`}
function mt(s,v){const m=st.m;if(!s)m.l=v;else if(m.l!==null){if(v===m.l)m.d.push(v);else m.x++;m.l=null}render()}
function startPlace(){const ex=U.flatMap((u,ui)=>shuf(u.l.flatMap(l=>l.w)).slice(0,2)).map((x,i)=>mkEx(x,i%2?'type':'choice'));S.sess={lk:'nivel',ex,i:0,ok:0,intro:1,sec:0,t:Date.now(),pl:1};save();location.hash='#/lic'}
let fl={};
function tg(k){S.fav[k]=!S.fav[k];save();render()}
function rate(k,ok){upd(k,ok);fl[k]=0;save();render()}
function saved(){const L=Object.keys(S.fav).filter(k=>S.fav[k]&&VK[k]);
 return`<h1>Salvos</h1>`+(L.length?`<p class="mu">Toque no cartão para virar. Depois de ver a tradução, marque se foi fácil ou difícil: isso ajusta a revisão.</p>`+L.map(k=>{const x=VK[k],f=fl[k];return`<div class="card"><button class="opt" style="text-align:center;min-height:110px" aria-pressed="${!!f}" aria-label="Cartão: ${esc(x.it)}. ${f?'Tradução: '+esc(x.pt):'Toque para ver a tradução'}" onclick="fl['${k}']=!fl['${k}'];render()"><span class="big">${esc(f?x.pt:x.it)}</span><br><span class="mu">${f?esc(x.it):'toque para virar'}</span></button><div class="row" style="margin-top:8px"><span><button class="btn s" onclick="say(${JSON.stringify(x.it).replace(/"/g,'&quot;')})">Ouvir</button> <button class="btn s" onclick="tg('${k}')">Remover</button></span>${f?`<span><button class="btn s" onclick="rate('${k}',0)">Difícil</button> <button class="btn s" onclick="rate('${k}',1)">Fácil</button></span>`:''}</div></div>`}).join(''):`<div class="card"><p>Nada salvo ainda. Toque em ☆ nas lições ou na aba Palavras para guardar palavras e frases aqui.</p></div>`)}
function exp(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({...S,language:course})],{type:'application/json'}));a.download='parlo-'+course+'-progresso.json';a.click()}
function onb(){return`<div style="text-align:center">${LOGO}<h1>PARLO</h1><p class="mu">Italiano para quem fala português. Sem conta, direto ao ponto.</p></div><div class="card"><label for="o1">Como podemos te chamar?</label><input type="text" id="o1"><label for="o2">Nível</label><select id="o2"><option value="0">Começando do zero</option><option value="1">Já conheço o básico</option></select><label for="o3">Objetivo</label><select id="o3"><option>viagens</option><option>conversação</option><option>cultura</option><option>estudo geral</option></select><label for="o4">Meta diária</label><select id="o4"><option>5</option><option selected>10</option><option>15</option><option>20</option></select></div><button class="btn w" onclick="fin(1)">Começar</button><p></p><button class="btn s w" onclick="fin(1);startPlace()">Começar com teste de nivelamento</button><p></p><button class="btn s w" onclick="fin(0)">Pular por agora</button>`}
function fin(f){if(f){S.p.name=document.getElementById('o1').value.trim();S.p.lvl=+document.getElementById('o2').value;S.p.goal=document.getElementById('o3').value;S.p.min=+document.getElementById('o4').value}S.p.on=1;save();location.hash='#/';render()}
function theme(){const r=document.documentElement;r.dataset.theme=S.p.theme==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):S.p.theme;r.dataset.rm=S.p.rm}
// Visual system adapted from the supplied Figma reference.
const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',trail:'<path d="M5 3v18M5 5h14l-3 4 3 4H5"/>',rev:'<path d="M4 8h12a4 4 0 0 1 0 8H8M4 8l4-4M4 8l4 4M20 16l-4 4"/>',book:'<path d="M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1zm0 0v15"/>',save:'<path d="M6 3h12v18l-6-4-6 4z"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M5 21v-3a7 7 0 0 1 14 0v3"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7z"/>',fire:'<path d="M12 2c3 6-3 6 1 10 2-1 3-3 3-5 7 8 3 15-4 15S2 14 7 8c0 4 2 5 3 5-2-5 2-6 2-11z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',sound:'<path d="M11 4 5 9H2v6h3l6 5zM15 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',check:'<path d="m5 12 4 4L20 5"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',idea:'<path d="M9 18h6m-6 3h6M8 14a7 7 0 1 1 8 0l-1 2H9z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.book}</svg>`}
function heading(k,t,d,b=''){return `<div class="page-heading"><div><p class="eyebrow">${k}</p><h1>${t}</h1><p class="mu">${d}</p></div>${b}</div>`}
function badge(t){return `<span class="badge">${t}</span>`}
function audioButton(x){return `<button class="btn s audio" ${aud()?'':'disabled'} aria-label="Ouvir ${esc(x.it)}" onclick="say(this.dataset.text)" data-text="${esc(x.it)}">${icon('sound')} Ouvir</button>`}
const oldLessonView=lessonView,oldProfile=prof,oldOnboarding=onb;
home=function(){const [u,l]=nextL(),rs=S.sess&&U.flatMap(x=>x.l).find(x=>x.k===S.sess.lk),m=Math.floor(secs()/60),pc=Math.min(100,secs()/60/S.p.min*100),h=new Date().getHours(),wd=V[Math.floor(Date.now()/DAY)%V.length];const wk=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {xp:(S.days[d.toLocaleDateString('sv')]||{xp:0}).xp,label:i===6?'Hoje':i===5?'Ontem':d.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.','')}}),mx=Math.max(1,...wk.map(x=>x.xp));return heading('BEM-VINDO AO PARLO',`${language().greet[h<12?0:h<18?1:2]}, ${esc(S.p.name||'estudante')}!`,`Seu próximo passo no ${language().target} começa aqui.`)+`<div class="home-lead"><section class="card hero"><p class="eyebrow">CONTINUE APRENDENDO</p><h2>${esc(rs?.t||l.t)}</h2><p class="mu">${esc(rs?U.find(x=>x.l.includes(rs)).t:u.t)} · Lição ${Number((rs||l).k.split('-')[1])+1}</p><button class="btn" onclick="${S.sess?"location.hash='#/lic'":`startLesson('${l.k}')`}">${icon('arrow')} ${S.sess?'Continuar lição':'Começar lição'}</button><div class="ciao" aria-hidden="true"><em>${language().hello}</em><small>${language().bye}</small></div></section><section class="card goal"><div class="row"><p class="eyebrow">META DIÁRIA</p>${icon('target')}</div><p><span class="big">${m}</span><span class="mu"> / ${S.p.min} min</span></p><div class="bar"><i style="width:${pc}%"></i></div><p class="mu">Cada minuto conta. Continue construindo seu hábito.</p></section></div><div class="stats">${[['bolt',S.xp,'XP total'],['book',Object.keys(S.done).length,'Lições concluídas'],['trail',Object.keys(S.srs).length,'Palavras estudadas'],['rev',due().length,'Revisões']].map(([i,n,t])=>`<a class="stat" href="#/${i==='rev'?'rev':i==='trail'?'vocab':'perfil'}">${icon(i)}<div><strong>${n}</strong><small>${t}</small></div></a>`).join('')}</div><div class="home-bottom"><section class="card weekly"><div class="row"><b>Últimos 7 dias (XP)</b>${badge(wk.reduce((a,x)=>a+x.xp,0)+' XP nesta semana')}</div><div class="weekchart">${wk.map(x=>`<div class="day"><span>${x.xp}</span><i style="height:${Math.max(2,x.xp/mx*100)}px"></i><small>${x.label}</small></div>`).join('')}</div></section><section class="card daily"><p class="eyebrow">PRATIQUE A ESCUTA</p><h2>Um pouco de ${language().target} por dia.</h2><p class="mu">${esc(wd.it)} — ${esc(wd.pt)}</p>${audioButton(wd)}<p class="tiny">${aud()?'Ouça e aproxime-se da pronúncia.':'Áudio indisponível neste navegador.'}</p></section></div>`};
trail=function(){const [,next]=nextL();return heading('PASSO A PASSO','Trilha de aprendizado','Das primeiras palavras às suas primeiras conversas.')+`<div class="card placement row"><div><b>Não sabe por onde começar?</b><p class="mu">Encontre seu ponto de partida no ${language().target}.</p></div><button class="btn s" onclick="startPlace()">${icon('arrow')} Teste de nivelamento</button></div><div class="units">`+U.map((u,ui)=>{const dn=u.l.filter(l=>S.done[l.k]).length,sd=Object.keys(S.srs).filter(k=>k.startsWith(ui+'-')).length;return `<section class="unit"><div class="row"><p class="eyebrow">UNIDADE ${String(ui+1).padStart(2,'0')}</p>${badge(dn+'/3 lições')}</div><h2>${esc(u.t)}</h2><p class="mu unit-desc">${esc(u.d)}</p>${u.l.map(l=>{const done=!!S.done[l.k],cur=l.k===next.k||S.sess?.lk===l.k;return `<button class="lc ${done?'ok':cur?'cur':''}" onclick="startLesson('${l.k}')"><span class="nm">${icon(done?'check':cur?'arrow':'book')}</span><span class="tx"><b>${esc(l.t)}</b><span class="sb">${esc(l.w.slice(0,3).map(x=>x.it).join(' · '))}</span><span class="status">${done?'Concluída':cur?'Iniciar →':'Disponível'}</span></span></button>`}).join('')}<button class="lc rv" ${sd?'':'disabled'} onclick="startRevU(${ui})">${icon('rev')}<span class="tx"><b>Revisão: ${esc(u.t)}</b><span class="sb">${sd} itens estudados</span></span></button></section>`}).join('')+'</div>'};
rev=function(){const n=due().length;return heading('RECORDAR É APRENDER','Revisão','Um espaço para consolidar o que você já aprendeu.',badge(n+' itens pendentes'))+`<section class="card empty"><div class="empty-icon">${icon(n?'rev':'check')}</div><p class="eyebrow">${n?'VAMOS PRATICAR':'TUDO EM DIA'}</p><h2>${n?`${n} palavras esperando por você.`:'Nada para revisar agora.'}</h2><p class="mu">${n?'Uma pequena revisão faz uma grande diferença.':'Conclua lições para gerar itens.'}</p>${n?`<button class="btn" onclick="startRev()">${icon('arrow')} Revisar agora</button>`:`<a class="btn" href="#/trilha">${icon('arrow')} Aprender agora</a>`}</section><aside class="hint">${icon('idea')}<div><p class="eyebrow">NO TEMPO CERTO</p><p class="mu">Se você acertar, a palavra entra na revisão novamente em 1, 3, 7, 14 e 30 dias. Se errar, volta em 10 min.</p></div></aside>`};
vocab=function(){const L=V.filter(x=>(!cat||(cat==='fav'?S.fav[x.k]:x.c===cat))&&norm(x.it+' '+x.pt).includes(norm(q)));return heading('PALAVRAS QUE FICAM','Vocabulário','Reencontre suas palavras, ouça a pronúncia e salve suas favoritas.',badge(Object.keys(S.srs).length+' palavras estudadas'))+`<div class="filters"><div class="search">${icon('search')}<input type="text" aria-label="Buscar" placeholder="Buscar em italiano ou português" value="${esc(q)}" oninput="searchWords(this)"></div><select aria-label="Filtro" onchange="cat=this.value;render()"><option value="">Todas as unidades</option><option value="fav" ${cat==='fav'?'selected':''}>Favoritos</option>${U.map(u=>`<option ${cat===u.t?'selected':''}>${esc(u.t)}</option>`).join('')}</select></div>`+U.map(u=>{const W=L.filter(x=>x.c===u.t);return W.length?`<section class="word-group"><div class="group-head row"><span class="eyebrow">${esc(u.t)}</span><span class="tiny">${W.length} palavras</span></div>${W.map(x=>`<div class="word-row"><div class="word"><b>${esc(x.it)}</b><small>${esc(x.pt)}</small></div><div class="word-state"><small>${esc(x.c)}</small><small>${S.srs[x.k]?(S.srs[x.k].due<=Date.now()?'◷ Revisar':'◎ Em dia'):'Ainda não estudada'}</small></div><div class="word-actions"><button class="btn s square ${S.fav[x.k]?'gold':''}" aria-label="Salvar ${esc(x.it)}" aria-pressed="${!!S.fav[x.k]}" onclick="tg('${x.k}')">${icon('star')}</button>${audioButton(x)}</div></div>`).join('')}</section>`:''}).join('')+(!L.length?'<section class="card empty"><h2>Nenhuma palavra encontrada.</h2><p class="mu">Tente outra busca ou unidade.</p></section>':'')};
function searchWords(el){const pos=el.selectionStart;q=el.value;render();const n=document.querySelector('[aria-label="Buscar"]');n.focus();n.setSelectionRange(pos,pos)}
