lessonView=function(){const s=S.sess;if(!s)return oldLessonView();if(s.intro)return `<div class="exercise">${oldLessonView()}</div>`;const l=U.flatMap(u=>u.l).find(x=>x.k===s.lk),u=U.find(u=>u.l.includes(l));return `<div class="lesson-intro"><section><p class="eyebrow coral">${esc(u.t)} · LIÇÃO ${Number(l.k.split('-')[1])+1}</p><h1>${esc(l.t)}</h1><p>Toda boa conversa começa com uma palavra.</p><div class="culture"><p class="eyebrow gold">${icon('book')} UM POUCO DE CULTURA</p><h2><em>${esc(l.w[0].it)}!</em></h2><p class="mu">${esc(l.n)}</p></div><div class="row">${badge(l.w.length+' vocábulos')}${badge(l.w.length+' exercícios')}</div></section><section><div class="row"><h3>Antes de começar</h3><span class="tiny">Leia, ouça e familiarize-se.</span></div><div class="word-group">${l.w.map(x=>`<div class="word-row"><div class="word"><b>${esc(x.it)}</b><small>${esc(x.pt)}</small></div><div class="word-actions"><button class="btn s square ${S.fav[x.k]?'gold':''}" aria-label="Salvar ${esc(x.it)}" aria-pressed="${!!S.fav[x.k]}" onclick="tg('${x.k}')">${icon('star')}</button>${audioButton(x)}</div></div>`).join('')}<p class="tiny audio-note">${aud()?'Ouça no seu ritmo.':'Sem voz compatível neste navegador: as atividades usam texto.'}</p></div><button class="btn w" onclick="S.sess.intro=1;S.sess.t=Date.now();save();render()">${icon('arrow')} Começar</button></section></div>`};
function render(){theme();const r=(location.hash.slice(2)||'').split('?')[0],A=document.getElementById('app'),N=document.getElementById('nav'),B=document.getElementById('topbar'),focus=r==='lic',on=!S.p.on;document.body.classList.toggle('focus-mode',focus);document.body.classList.toggle('onboarding',on);A.dataset.page=r||'home';if(on){N.innerHTML='';B.innerHTML=`<a class="brand" href="#/">PARLO</a><span class="mu">${language().motto}</span>`;A.innerHTML=oldOnboarding();return}const T=[['','Início','home'],['trilha','Trilha','trail'],['rev','Revisão','rev'],['frases','Frases','book'],['vocab','Vocabulário','book'],['salvos','Salvos','save'],['perfil','Perfil','user']];N.innerHTML=`<a class="brand" href="#/">PARLO<small>${language().motto.toUpperCase()}</small></a>${coursePicker()}<div class="nav-links">${T.map(([k,t,i])=>`<a href="#/${k}" ${k===r?'aria-current="page"':''}>${icon(i)}<span>${t}</span><i></i></a>`).join('')}</div><div class="sidebar-bottom"><div class="streak-box">${icon('fire')}<b>${streak()} ${streak()===1?'dia':'dias'} de sequência</b><p>Um pouco de ${language().target},<br>todos os dias.</p></div><a class="sidebar-user" href="#/perfil"><span class="av">${esc((S.p.name||'P').slice(0,2).toUpperCase())}</span><span><b>${esc(S.p.name||'Estudante')}</b><small>Estudante de ${language().target}</small></span></a></div>`;const l=S.sess&&U.flatMap(u=>u.l).find(x=>x.k===S.sess.lk),u=l&&U.find(u=>u.l.includes(l));B.innerHTML=focus?`<a class="brand" href="#/">PARLO</a><span class="tiny">${l?esc(u.t)+' / '+esc(l.t):'Prática de idiomas'}</span><a class="btn s" href="#/">${icon('close')} Sair</a>`:`<span class="top-motto">Seu ${language().target}, um passo de cada vez.</span><div class="top-stats"><span class="gold">${icon('bolt')} ${S.xp} XP</span><span>${icon('fire')} ${streak()} ${streak()===1?'dia':'dias'}</span><a href="#/perfil">${esc(S.p.name||'Estudante')}</a></div>`;const R={'':home,trilha:trail,rev,frases:sentenceLibrary,vocab,salvos:saved,perfil:prof,lic:lessonView,fim};A.innerHTML=R[r]?R[r]():heading('404','Página não encontrada','Este caminho ainda não fala o seu idioma.')+'<a class="btn" href="#/">Voltar ao início</a>';if(focus&&S.sess?.intro){const ex=S.sess.ex[S.sess.i];A.querySelectorAll('.opt').forEach((el,i)=>{el.insertAdjacentHTML('afterbegin',`<span class="option-number">${i+1}</span>`);if(st.res){el.classList.toggle('correct',el.dataset.v===ex.a);el.classList.toggle('incorrect',el.dataset.v===st.sel&&!st.res.ok)}})}if(r==='perfil'){const grid=A.querySelector('.profile-grid');grid.firstElementChild?.remove();grid.children[1]?.classList.add('progress-card');grid.children[2]?.classList.add('data-card')}if(!navigator.onLine)A.insertAdjacentHTML('afterbegin','<div class="offline">Você está offline. O progresso continua salvo neste navegador.</div>')}
