let transitionBusy=false,noticeTimer;
function notice(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>el.classList.remove('visible'),5000)}
async function api(path,options={}){
 const response=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});
 const data=await response.json().catch(()=>({error:'Resposta inesperada do servidor.'}));
 if(!response.ok)throw Object.assign(Error(data.error||'Não foi possível concluir.'),{status:response.status,data});return data;
}
function freshState(){const n=DEF();if(account)n.p.name=account.name;return n}
function usableState(s){return validateProgress(s)}
function restoreState(s){const d=freshState();return usableState(s)?{...d,...s,p:{...d.p,...s.p}}:d}
async function openCourse(lang){
 setCourse(lang);q='';cat='';fl={};conflict=null;
 const key=stateKey(owner(),lang),cached=records[key]||await localGet(key);let record=cached;
 if(account){
  try{const remote=await api('/api/progress/'+lang);
   if(cached?.dirty){if(cached.revision!==remote.revision){conflict={key,remote};syncState='conflict'}else syncState='pending'}
   else{record={state:remote.state||freshState(),revision:remote.revision,dirty:false,localVersion:0};syncState='saved';await localPut(key,record)}
  }catch(e){if(e.status===401)throw e;syncState='offline'}
 }else if(!record&&lang==='it'){const legacy=await localGet('s');if(usableState(legacy))record={state:legacy,revision:0,dirty:true,localVersion:1}}
 record=record||{state:freshState(),revision:0,dirty:false,localVersion:0};records[key]=record;S=restoreState(record.state);st=S.sess?.feedback||{};
 await localPut('language:'+owner(),lang);
}
async function syncProgress(){
 if(!account||syncBusy||conflict)return !conflict;
 const id=account.id,lang=course,key=stateKey(id,lang),record=records[key];if(!record?.dirty)return true;
 syncBusy=true;syncState='syncing';paintSync();
 const version=record.localVersion;
 try{
  const result=await api('/api/progress/'+lang,{method:'PUT',body:JSON.stringify({state:record.state,revision:record.revision})});
  const latest=records[key];records[key]={...latest,revision:result.revision,dirty:latest.localVersion!==version};await localPut(key,records[key]);
  if(account?.id===id&&course===lang){syncState=records[key].dirty?'pending':'saved';if(records[key].dirty)setTimeout(syncProgress,500)}
  return true;
 }catch(e){
  if(account?.id===id&&course===lang){if(e.status===409){conflict={key,remote:e.data};syncState='conflict'}else if(e.status===401){syncState='expired'}else syncState=navigator.onLine?'error':'offline'}return false;
 }finally{syncBusy=false;paintSync()}
}
function paintSync(){const el=document.getElementById('sync-control');if(el){el.textContent=syncLabel();el.dataset.state=syncState}const target=document.getElementById('conflict-slot');if(target)target.innerHTML=conflictView()}
function syncLabel(){return ({local:'Só neste dispositivo',saved:'Salvo na conta',pending:'Alterações pendentes',syncing:'Salvando…',offline:'Offline · salvo aqui',error:'Falha ao sincronizar',expired:'Sessão expirada · entre de novo',conflict:'Escolher versão'})[syncState]||'Salvar progresso'}
function conflictView(){if(!conflict)return '';return `<aside class="sync-conflict" role="alert"><b>Há duas versões do seu progresso.</b><p>Outro dispositivo salvou alterações. Escolha qual versão continuar usando. Você pode exportar seu progresso local antes.</p><div class="row"><button class="btn s" onclick="exp()">Exportar versão local</button><button class="btn s" onclick="resolveConflict('remote')">Usar versão da conta</button><button class="btn" onclick="resolveConflict('local')">Manter este dispositivo</button></div></aside>`}
async function resolveConflict(choice){if(!conflict||syncBusy)return;const {key,remote}=conflict;if(choice==='remote'){records[key]={state:remote.state||freshState(),revision:remote.revision,dirty:false,localVersion:0};S=restoreState(records[key].state);st=S.sess?.feedback||{};syncState='saved'}else records[key]={...records[key],revision:remote.revision,dirty:true};conflict=null;await localPut(key,records[key]);render();if(choice==='local')await syncProgress()}
async function changeCourse(lang){if(!['it','en'].includes(lang)||transitionBusy||lang===course)return;transitionBusy=true;clearTimeout(saveTimer);try{if(syncBusy){notice('Aguarde o salvamento terminar.');return}if(account&&records[stateKey(owner(),course)]?.dirty&&!await syncProgress()){notice('Resolva a sincronização antes de trocar de idioma.');return}const prefs={...S.p};await openCourse(lang);if(prefs.on&&!S.p.on){S.p={...prefs};await save()}if(account){await api('/api/auth/preferences',{method:'PATCH',body:JSON.stringify({language:lang})});account.preferred_language=lang}location.hash='#/';render();if(account&&records[stateKey(owner(),course)]?.dirty)syncProgress()}catch(e){notice(e.message)}finally{transitionBusy=false;render()}}
function authView(){return `<section class="auth-shell"><div class="auth-story"><a class="brand" href="#/">PARLO<small>UM NOVO IDIOMA. NOVAS CONVERSAS.</small></a><p class="eyebrow">ITALIANO & INGLÊS</p><h1>Seu próximo<br>mundo começa<br>com um <em>hello.</em></h1><p class="mu">Um pouco por dia, no seu ritmo. Entre para levar seu progresso aonde você for.</p><div class="auth-words"><span>Ciao.</span><span>Hello.</span><span>Vamos?</span></div></div><div class="card auth-form"><p class="eyebrow">BEM-VINDO AO PARLO</p><h2>${authMode==='register'?'Uma conta, dois idiomas.':'Bom te ver por aqui.'}</h2><p class="mu">${authMode==='register'?'Crie sua conta e comece a estudar.':'Entre e continue de onde parou.'}</p><div class="auth-tabs"><button class="${authMode==='login'?'active':''}" onclick="authMode='login';authError='';render()">Entrar</button><button class="${authMode==='register'?'active':''}" onclick="authMode='register';authError='';render()">Criar conta</button></div><form onsubmit="submitAuth(event)">${authMode==='register'?'<label for="auth-name">Como podemos te chamar?</label><input id="auth-name" name="name" autocomplete="given-name" required maxlength="80" placeholder="Seu nome"><label class="honeypot" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><fieldset class="signup-languages"><legend>Qual idioma você quer aprender primeiro?</legend><label><input type="radio" name="language" value="it" checked><span>Italiano<small>Ciao, mondo.</small></span></label><label><input type="radio" name="language" value="en"><span>Inglês<small>Hello, world.</small></span></label></fieldset>':''}<label for="auth-email">E-mail</label><input id="auth-email" name="email" type="email" autocomplete="email" required maxlength="254" placeholder="voce@exemplo.com"><label for="auth-password">Senha</label><input id="auth-password" name="password" type="password" autocomplete="${authMode==='register'?'new-password':'current-password'}" required minlength="8" maxlength="128" placeholder="Pelo menos 8 caracteres"><div id="auth-error" class="form-error" role="alert">${esc(authError)}</div><button class="btn w" type="submit" ${authBusy?'disabled':''}>${authBusy?'Aguarde…':authMode==='register'?'Criar conta':'Entrar'} ${icon('arrow')}</button></form><p class="tiny auth-note">${authMode==='register'?'O cadastro libera o acesso imediatamente, sem confirmação de e-mail.':'Seu progresso de italiano e inglês fica salvo na sua conta.'}</p><button class="text-btn guest-link" onclick="startGuest()">Explorar sem conta neste dispositivo</button><div class="legal-links"><a href="/privacidade" target="_blank" rel="noopener">Privacidade</a><a href="/termos" target="_blank" rel="noopener">Termos</a><a href="/cookies" target="_blank" rel="noopener">Cookies</a></div></div></section>`}
async function submitAuth(event){event.preventDefault();if(authBusy)return;const form=event.target,b={email:form.elements.email.value,password:form.elements.password.value};if(authMode==='register'){b.name=form.elements.name.value;b.language=form.elements.language.value;b.website=form.elements.website.value;}authBusy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='Aguarde…';document.getElementById('auth-error').textContent='';try{const d=await api('/api/auth/'+authMode,{method:'POST',body:JSON.stringify(b)});account=d.user;guest=false;records={};conflict=null;const lang=account.preferred_language||'it';await openCourse(lang);authError='';location.hash='#/';render()}catch(e){authError=e.message;const box=document.getElementById('auth-error');if(box)box.textContent=authError;else{account=null;render()}}finally{authBusy=false;const button=document.querySelector('.auth-form [type=submit]');if(button){button.disabled=false;button.textContent=authMode==='register'?'Criar conta':'Entrar'}}}
async function startGuest(){guest=true;account=null;records={};syncState='local';await openCourse(await localGet('language:guest')||'it');location.hash='#/';render()}
