async function importGuestProgress(){const record=await localGet(stateKey('guest',course)),legacy=course==='it'?await localGet('s'):null;const data=record?.state||legacy;if(!usableState(data)){notice('Nenhum progresso local encontrado neste idioma.');return}if(!confirm('Substituir o progresso deste idioma na sua conta pelos dados locais? Exporte um backup antes se precisar.'))return;S=restoreState(data);S.p.on=1;S.sess=null;st={};await save();render();await syncProgress()}
