setInterval(()=>{if(account&&!document.hidden&&!syncBusy&&!conflict&&records[stateKey(owner(),course)]?.dirty)syncProgress()},15000);
// ---- Applied learning: authored dialogues, equivalence lists, topic review and opt-in speech ----
function lessonForKey(key){return U.flatMap(u=>u.l).find(l=>l.k===key.split('-').slice(0,2).join('-'))}
function learningStats(){return S.learning||(S.learning={topics:{},mistakes:[]})}
const originalMkEx=mkEx;
mkEx=function(x,kind){const ex=originalMkEx(x,kind);ex.topic=x.topic;ex.why=x.tip;ex.alt=['type','order','listen'].includes(ex.t)?x.alt||[]:[];ex.context=lessonForKey(x.k)?.goal||'';return ex};
function dialogueExercise(l){const d=l.dialogue,reply=d[2];return {t:'dialogue',k:(l.w.find(x=>norm(x.it)===norm(reply.text))||l.w[0]).k,topic:l.topic,q:`Você é ${reply.speaker.toLowerCase()}. Qual fala continua a conversa?`,a:reply.text,o:shuf([reply.text,d[0].text,d[1].text,d[3].text].filter((x,i,a)=>a.indexOf(x)===i)),ctx:d.slice(0,2),context:l.goal,why:`O objetivo aqui é: ${l.goal} A fala “${reply.text}” continua a conversa. Compare com a resposta seguinte: “${d[3].text}” (${d[3].pt}).`,alt:equivalents(reply.text,course)};}
function comprehensionExercise(l){return {t:'context',k:l.w[0].k,topic:l.topic,q:l.task.q,a:l.task.a,o:shuf([l.task.a,...l.task.o]),ctx:l.dialogue,context:l.goal,why:l.task.why,alt:[]}}
function lessonExercises(l,extra=false){
 const out=[],priority=new Set(S.last?.lessonKey===l.k?S.last.missedKeys||[]:[]),words=extra?[...l.w].sort((a,b)=>Number(priority.has(b.k))-Number(priority.has(a.k))):l.w;
 const add=(x,kind,stage)=>{const e=stage==='practice'?guidedExpression(x,kind):mkEx(x,kind);e.stage=stage;out.push(e)};
 if(!extra)words.forEach((x,i)=>add(x,i%2?'listen':'choice','discover'));
 words.forEach(x=>add(x,'order','practice'));
 // Every expression must be recalled, including short words that cannot be ordered.
 shuf(words).forEach(x=>add(x,'type','recall'));
 for(const word of l.w.filter(x=>x.it.split(' ').length>1).slice(0,2)){const e=mkEx(word,'order');e.audioOrder=true;e.audioText=word.it;e.q='Ouça e monte a expressão com as peças.';e.stage='listen';out.push(e)}
 for(const e of [dialogueExercise(l),comprehensionExercise(l),dialogueMeaningExercise(l)]){e.stage='use';out.push(e)}
 if(!extra){const prior=V.filter(x=>S.srs[x.k]&&!l.w.some(y=>y.k===x.k)).sort((a,b)=>S.srs[a.k].due-S.srs[b.k].due);if(prior.length){const e=mkEx(prior[0],'type');e.mixed=true;e.stage='recall';out.push(e)}}
 return out;
}
startLesson=function(k){if(transitionBusy){notice('Aguarde a troca de idioma terminar.');return}stopSpeech();if(S.sess?.lk===k){location.hash='#/lic';render();return}const l=U.flatMap(u=>u.l).find(l=>l.k===k);if(!l){notice('Lição não encontrada.');return}S.sess={lk:k,lessonKey:k,lessonMode:'learn',missedKeys:[],srsSeen:[],ex:lessonExercises(l),i:0,ok:0,intro:0,sec:0,t:Date.now()};st={};save();location.hash='#/lic';render()};
const originalGrade=grade;
grade=function(answer,expected,alternatives=[]){const valid=[expected,...alternatives].map(norm);if(valid.includes(norm(String(answer||''))))return {ok:1,equivalent:norm(String(answer||''))!==norm(expected)};return originalGrade(String(answer||''),expected)};
function explainAnswer(e,answer,result){
 if(result.ok)return result.equivalent?'Sua formulação também é natural e tem o mesmo sentido nesta atividade. '+(e.why||''):e.why||VK[e.k]?.tip||'Confira a expressão completa e seu uso no contexto.';
 if(e.t==='dialogue')return 'Essa fala não dá continuidade ao papel indicado neste ponto da conversa. '+e.why;
 if(e.t==='context')return e.why;
 const a=norm(String(answer||'')),expected=norm(e.a);let detail='';
 if(course==='en'){
  if(/\bi (am|have) (hungry|thirsty|sleepy|cold|tired)\b/.test(a)&&/\bi have\b/.test(a))detail='Em inglês, diga I am hungry/thirsty/tired, usando to be para esse estado. ';
  else if(/\b(he|she|it) have\b/.test(a))detail='Com he, she ou it, have vira has no presente afirmativo. ';
  else if(/\bdid(n't| not)? (went|saw|bought|understood)\b/.test(a))detail='Depois de did/didn’t, o verbo precisa voltar à forma base: go, see, buy, understand. ';
  else if(/\bi am (study|work|live|speak)\b/.test(a))detail='Para esse hábito, use I study/work/live/speak, sem am antes do verbo base. ';
  else if(/\b(not|n't|cannot)\b/.test(expected)&&!/(not|n't|cannot)/.test(a))detail='Faltou a negação, o que muda o sentido da resposta. ';
 }else{
  if(/\bsono (fame|sete|sonno)\b/.test(a))detail='Esses estados usam avere: ho fame, ho sete, ho sonno. ';
  else if(/\bio (è|ha|sei)\b/.test(a))detail='Com io, use sono para essere e ho para avere. ';
  else if(expected.startsWith('non ')&&!a.startsWith('non '))detail='Faltou non antes do verbo: a frase pedida é negativa. ';
 }
 return (result.m?result.m+' ':'')+detail+(e.why||VK[e.k]?.tip||'Confira a pessoa do verbo, a ordem e as palavras da expressão apresentada.');
}
function recordAttempt(e,ok,answer){const data=learningStats(),topic=e.topic||VK[e.k]?.topic||'present',t=data.topics[topic]||{attempts:0,correct:0,misses:0,streak:0,last:0};t.attempts++;t.correct+=ok?1:0;t.misses+=ok?0:1;t.streak=ok?t.streak+1:0;t.last=Date.now();data.topics[topic]=t;if(!ok){data.mistakes.unshift({key:e.k,type:e.t,answer:String(answer||'Associação incorreta').slice(0,200),expected:e.a.slice(0,300),topic,at:Date.now()});data.mistakes=data.mistakes.slice(0,40)}}
check=function(){const s=S.sess;if(!s||st.res)return;const e=s.ex[s.i];let answer=e.t==='order'?(st.pick||[]).join(' '):e.t==='type'?document.getElementById('ti').value:st.sel;const result=e.t==='match'?{ok:st.m?.x?0:1}:grade(answer,e.a,e.alt||[]);st.answer=String(answer||'');st.res={...result,explanation:explainAnswer(e,answer,result)};if(result.ok)s.ok++;
 if(s.pl){const u=e.k.split('-')[0];s.pu=s.pu||{};s.pu[u]=(s.pu[u]||0)+result.ok}
 else if(!s.builderKey){if(e.t==='match'){e.ps.forEach(p=>{const x=VK[p.k]||V.find(x=>x.c===VK[e.k].c&&x.it===p.it&&x.pt===p.pt);if(x)upd(x.k,!(st.m.bad||[]).includes(p.pt))})}else upd(e.k,result.ok);recordAttempt(e,result.ok,answer)}
 const stats=S.acc[e.t]||[0,0];stats[0]+=result.ok;stats[1]++;S.acc[e.t]=stats;scheduleLessonRetry(s,e,result.ok);s.feedback=structuredClone(st);save();render();
};
mt=function(side,value){const m=st.m;if(!m||st.res||m.d.includes(value))return;if(!side)m.l=value;else if(m.l!==null){if(value===m.l)m.d.push(value);else{m.x++;m.bad=m.bad||[];m.bad.push(m.l)}m.l=null}render()};
function dialogueMarkup(lines,{translations=false,reveal=false}={}){return `<div class="dialogue-lines">${lines.map((line,i)=>`<div class="dialogue-line ${i%2?'right':''}"><span>${esc(line.speaker)}</span><p lang="${language().voice}">${esc(line.text)}</p>${translations?`<small>${esc(line.pt)}</small>`:''}</div>`).join('')}</div>`}
let dialoguePlayer=0;
function stopAudio(){dialoguePlayer++;if('speechSynthesis'in window)speechSynthesis.cancel()}
function playDialogue(key,slow=false){const l=lessonForKey(key);if(l)playLines(l.dialogue,slow)}
function playCurrentDialogue(slow=false){const e=S.sess?.ex[S.sess.i];if(e?.ctx)playLines(e.ctx,slow)}
function playLines(lines,slow=false){if(!aud()){notice('Não há voz compatível disponível. Use a transcrição.');return}stopAudio();const run=dialoguePlayer;let i=0;function speakNext(){if(run!==dialoguePlayer||i>=lines.length)return;const line=lines[i++],u=new SpeechSynthesisUtterance(line.text);u.lang=language().voice;u.voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(language().voice.slice(0,2)));u.rate=slow?.65:.92;u.onend=speakNext;u.onerror=()=>{if(run===dialoguePlayer)notice('Não foi possível reproduzir a conversa. Use a transcrição.')};speechSynthesis.speak(u)}speakNext()}
function dialogueAudio(l,current=false){if(!l)return '';const action=current?'playCurrentDialogue(':`playDialogue('${l.k}',`;return `<div class="dialogue-audio"><button class="btn s" ${aud()?'':'disabled'} onclick="${action}false)">${icon('sound')} Ouvir conversa</button><button class="btn s" ${aud()?'':'disabled'} onclick="${action}true)">Mais devagar</button><button class="text-btn" onclick="stopAudio()">Parar</button></div>`}

function speakingPanel(l){const x=l.w.find(x=>x.it.split(' ').length>2)||l.w[0];return `<section class="speaking-panel"><div class="row"><p class="eyebrow">SUA VEZ DE FALAR · OPCIONAL</p>${badge('Sem perder pontos')}</div><h3 lang="${language().voice}">${esc(x.it)}</h3><p class="mu">${esc(x.pt)}</p><div class="speech-actions">${audioButton(x)}<button class="btn s" onclick="startSpeaking('${x.k}')">Praticar com microfone</button><button class="text-btn" onclick="stopSpeech(true)">Encerrar</button></div><p class="tiny">O reconhecimento pode usar um serviço do navegador e precisar de internet. A transcrição ajuda a praticar; ela não mede sua pronúncia. Nenhum áudio é enviado ao servidor do PARLO.</p><p id="speech-result" class="speech-result" aria-live="polite">Você também pode ouvir, repetir em voz alta e comparar por conta própria.</p></section>`}
let recognition=null,speechRun=0;
function stopSpeech(show=false){speechRun++;if(recognition){recognition.onend=null;recognition.onresult=null;recognition.onerror=null;try{recognition.abort()}catch{}recognition=null}if(show){const n=document.getElementById('speech-result');if(n)n.textContent='Prática encerrada. Você pode tentar novamente quando quiser.'}}
function startSpeaking(key){const x=VK[key],node=document.getElementById('speech-result'),API=window.SpeechRecognition||window.webkitSpeechRecognition;if(!x||!node)return;if(!API){node.textContent='O reconhecimento de fala não está disponível neste navegador. Ouça o exemplo e pratique sem microfone.';return}if(!window.isSecureContext){node.textContent='O microfone precisa de HTTPS ou localhost. Você ainda pode praticar sem ele.';return}stopSpeech();stopAudio();const run=speechRun,languageAtStart=course;recognition=new API();recognition.lang=language().voice;recognition.interimResults=false;recognition.maxAlternatives=1;node.textContent='Ouvindo… diga a frase acima. Você pode encerrar a qualquer momento.';
 recognition.onresult=event=>{if(run!==speechRun||course!==languageAtStart)return;const heard=event.results[0][0].transcript,match=grade(heard,x.it,x.alt);node.textContent='O navegador entendeu: “'+heard+'”. '+(match.ok?'A transcrição corresponde à frase ou a uma alternativa aceita.':'Compare com: “'+x.it+'”. Tente mais uma vez se quiser. Erros de transcrição também podem acontecer.');};
 recognition.onerror=event=>{if(run!==speechRun)return;node.textContent=event.error==='not-allowed'?'Acesso ao microfone não autorizado. Continue praticando sem ele ou ajuste a permissão do site.':event.error==='no-speech'?'Não foi detectada fala. Tente novamente quando quiser.':'O reconhecimento não está disponível agora. Continue com o exemplo e a transcrição.'};recognition.onend=()=>{if(run===speechRun&&node.textContent.startsWith('Ouvindo'))node.textContent='A escuta terminou sem uma transcrição. Tente novamente ou pratique sem microfone.'};try{recognition.start()}catch{node.textContent='Não foi possível iniciar o microfone. Tente novamente ou pratique sem ele.'}}
function startTargeted(topic){const words=Object.values(VK).filter(x=>x.topic===topic&&S.srs[x.k]).sort((a,b)=>S.srs[a.k].b-S.srs[b.k].b||S.srs[a.k].due-S.srs[b.k].due);if(!words.length){notice('Conclua uma lição deste assunto primeiro.');return}stopSpeech();const ex=words.slice(0,6).map((x,i)=>mkEx(x,['type','order','choice','cloze','type','listen'][i%6])),l=lessonForKey(words[0].k);if(l)ex.push(dialogueExercise(l),comprehensionExercise(l));S.sess={lk:'rev',ex,i:0,ok:0,intro:1,sec:0,t:Date.now(),practiceTopic:topic};st={};save();location.hash='#/lic';render()}
function topicInsights(){const topics=Object.entries(S.learning?.topics||{}).sort(([,a],[,b])=>(a.correct/a.attempts)-(b.correct/b.attempts));return `<section class="learning-insights"><div class="row"><div><p class="eyebrow">O QUE PRATICAR AGORA</p><h2>Seu aprendizado, por assunto.</h2></div><a class="btn s" href="#/conversas">Explorar conversas</a></div>${topics.length?`<div class="topic-grid">${topics.map(([key,t])=>{const pct=Math.round(t.correct/t.attempts*100),status=t.attempts<4?'Conhecendo o assunto':pct<70?'Precisa de prática':pct<90?'Em construção':'Acertos consistentes';return `<article class="card topic"><span class="eyebrow">${status}</span><h3>${esc(TOPIC_NAMES[key]||key)}</h3><p><b>${pct}%</b> <span class="mu">· ${t.correct}/${t.attempts} atividades corretas</span></p><div class="bar"><i style="width:${pct}%"></i></div><button class="btn s" onclick="startTargeted('${key}')">Praticar este assunto</button></article>`}).join('')}</div>`:'<div class="card"><p class="mu">Depois das primeiras atividades, você verá aqui os assuntos que precisam de mais prática. Esses indicadores refletem seus exercícios, não uma certificação de nível.</p></div>'}</section>`}
function conversationLibrary(){const scenes=U.flatMap((u,i)=>i<6?[u.l[0]]:u.l);return heading('CONVERSAS REAIS','Um idioma para viver.','Pratique situações completas: entender o contexto, escolher uma resposta e continuar a conversa.',badge(scenes.length+' situações'))+`<div class="scenario-grid">${scenes.map(l=>`<article class="card scenario"><p class="eyebrow">${esc(TOPIC_NAMES[l.topic])}</p><h2>${esc(l.t)}</h2><p class="mu">${esc(l.goal)}</p><blockquote lang="${language().voice}">“${esc(l.dialogue[0].text)}”</blockquote><button class="btn s" onclick="startLesson('${l.k}')">Praticar situação ${icon('arrow')}</button></article>`).join('')}</div>`}
const legacyLessonView=lessonView;
lessonView=function(){const s=S.sess;if(!s)return legacyLessonView();const l=U.flatMap(u=>u.l).find(l=>l.k===s.lk);let html=legacyLessonView();if(!s.intro&&l){return html+`<section class="conversation-study"><div class="row"><div><p class="eyebrow">A LÍNGUA EM CONTEXTO</p><h2>Antes das palavras, uma conversa.</h2></div>${badge('Situação guiada')}</div><p class="mu">${esc(l.goal)}</p>${dialogueAudio(l)}${dialogueMarkup(l.dialogue,{translations:true})}<p class="tiny">Leia os papéis, escute e depois tente responder sem consultar as traduções.</p></section>${speakingPanel(l)}`}
 const e=s.ex[s.i];return html;
};
const previousRender=render;
render=function(){previousRender();if(!authReady||(!account&&!guest)||!S.p.on)return;const A=document.getElementById('app'),route=(location.hash.slice(2)||'').split('?')[0];
 if(route==='conversas'){A.innerHTML='<div id="conflict-slot">'+conflictView()+'</div>'+conversationLibrary();return}
 if(route==='trilha'){A.insertAdjacentHTML('afterbegin','<div class="curriculum-banner"><b>Do básico às situações reais.</b><p>Unidades 1–6: fundamentos · 7–11: uso cotidiano · 12: primeiras experiências no passado e planos. Este percurso é introdutório e não certifica um nível completo.</p><a href="#/conversas">Ver situações do dia a dia →</a></div>')}
 if(route===''||route==='rev')A.insertAdjacentHTML('beforeend',topicInsights());if(route==='rev'&&S.learning?.mistakes?.length)A.insertAdjacentHTML('beforeend',`<section class="recent-mistakes"><p class="eyebrow">APRENDER COM AS TENTATIVAS</p><h2>Retome um ponto de cada vez.</h2>${S.learning.mistakes.slice(0,4).map(m=>`<article class="card row"><div><b>${esc(TOPIC_NAMES[m.topic])}</b><p class="mu">Uma resposta esperada: ${esc(m.expected)}</p></div><button class="btn s" onclick="startTargeted('${m.topic}')">Praticar</button></article>`).join('')}</section>`);
 if(route==='rev'&&!due().length&&Object.keys(S.srs).length){const empty=A.querySelector('.empty');empty?.classList.add('compact');const title=empty?.querySelector('h2'),description=empty?.querySelector('p.mu');if(title)title.textContent='Revisão espaçada em dia.';if(description)description.textContent='Suas próximas revisões já estão agendadas. Você pode reforçar os assuntos abaixo enquanto espera.'}
 if(route==='lic'&&S.sess&&!S.sess.intro){const activityCount=A.querySelector('.lesson-intro>section:first-child>.row .badge:last-child');if(activityCount)activityCount.textContent=S.sess.ex.length+' atividades';A.querySelector('.lesson-intro .btn.w')?.remove();A.insertAdjacentHTML('beforeend',`<button class="btn w lesson-start" onclick="stopAudio();stopSpeech();S.sess.intro=1;S.sess.t=Date.now();save();render()">Começar exercícios ${icon('arrow')}</button>`)}
 if(route==='lic'&&S.sess?.intro){const e=S.sess.ex[S.sess.i],area=A.querySelector('.exercise'),result=st.res;if(!area)return;area.classList.add('applied-exercise');area.insertAdjacentHTML('afterbegin',`<p class="eyebrow exercise-topic">${e.mixed?'REVISÃO DE OUTRO ASSUNTO':e.t==='dialogue'?'CONTINUE A CONVERSA':e.t==='context'?'ENTENDA A SITUAÇÃO':esc(TOPIC_NAMES[e.topic]||'PRÁTICA')} · ${esc(e.context||'')}</p>`);
 if(e.ctx){const before=area.querySelector('h2');let block;if(e.t==='context'){const source=lessonForKey(e.k);block=`<section class="exercise-dialogue">${dialogueAudio(source,true)}<p class="tiny">${aud()?'Ouça a conversa. Se precisar, abra a transcrição para acompanhar.':'Sem voz disponível: leia a conversa para continuar.'}</p>${aud()?`<details><summary>Mostrar transcrição</summary>${dialogueMarkup(e.ctx,{translations:!!result})}</details>`:dialogueMarkup(e.ctx,{translations:!!result})}</section>`}else block=`<section class="exercise-dialogue">${dialogueAudio(lessonForKey(e.k),true)}${dialogueMarkup(e.ctx,{translations:!!result})}</section>`;before.insertAdjacentHTML('beforebegin',block)}
 if(result){const fb=area.querySelector('.fb');fb.innerHTML=`<b>${result.ok?'✓ '+(result.equivalent?'Outra forma correta!':'Correto!'):'Vamos entender juntos.'}</b>${!result.ok&&st.answer?`<p>Sua resposta: <span>${esc(st.answer)}</span></p>`:''}<p>Uma resposta esperada: <strong lang="${language().voice}">${esc(e.a)}</strong></p><p class="feedback-why">${esc(result.explanation||explainAnswer(e,st.answer,result))}</p>${e.alt?.length?`<details><summary>Outras formas aceitas</summary><p>${e.alt.map(esc).join(' · ')}</p></details>`:''}<button class="btn s" aria-pressed="${!!S.fav[e.k]}" onclick="tg('${e.k}')">${S.fav[e.k]?'★ Frase salva':'☆ Salvar: '+esc(VK[e.k].it)}</button>`}
 }
};
const previousNext=next;next=function(){stopSpeech();stopAudio();previousNext()};
addEventListener('hashchange',()=>{stopSpeech();stopAudio()});
addEventListener('pagehide',()=>{stopSpeech();stopAudio()});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopSpeech();stopAudio()}});
const previousChangeCourse=changeCourse;
changeCourse=async function(lang){if(transitionBusy)return;stopSpeech();stopAudio();document.body.classList.add('changing-course');try{return await previousChangeCourse(lang)}finally{document.body.classList.remove('changing-course')}};

// ---- Organized bilingual vocabulary library ----
let lexCategory='overview',lexQuery='',lexRegister='all',lexSub='all',lexOnlySaved=false,lexPage=1;
const LEX_PAGE_SIZE=18;
function resetLexFilters(){lexCategory='overview';lexQuery='';lexRegister='all';lexSub='all';lexOnlySaved=false;lexPage=1}
const lexSections=()=>[...VOCAB_SECTIONS,{id:'course',title:'Vocabulário das aulas',description:'Retome as palavras e expressões ligadas à trilha que você já conhece.',topic:'present'}];
const LEX_SUB_ORDER={verbs:['Essenciais','Movimento','Rotina','Comunicação'],daily:['Casa','Pessoas e sentimentos','Tempo e rotina','Cidade e transporte','Trabalho e estudo','Tecnologia e comunicação'],phrases:['Perguntas úteis','Necessidades e imprevistos','Conversas e opiniões']};
function lexItems(){return [...VOCABULARY[course],...V.map(x=>({...x,category:'course',sub:x.c,register:'neutro',region:'Conteúdo das aulas',note:x.tip||'',forms:'',example:'',examplePt:''}))].sort((a,b)=>{const cats=lexSections().map(x=>x.id),category=cats.indexOf(a.category)-cats.indexOf(b.category);if(category)return category;const order=LEX_SUB_ORDER[a.category];return order?order.indexOf(a.sub)-order.indexOf(b.sub):0})}
function lexMatches(items){const query=flat(norm(lexQuery));return items.filter(x=>(lexCategory==='overview'||lexCategory==='all'||x.category===lexCategory)&&(lexSub==='all'||x.sub===lexSub)&&(lexRegister==='all'||x.register===lexRegister)&&(!lexOnlySaved||!!S.fav[x.k])&&(!query||flat(norm([x.it,x.pt,x.example,x.examplePt,x.sub,x.note,x.forms].join(' '))).includes(query)))}
function chooseLexTopic(id){if(!lexSections().some(x=>x.id===id)&&id!=='overview'&&id!=='all')return;lexCategory=id;lexSub='all';lexPage=1;lexFiltersOpen=true;renderLexFilters()}
function lexSearch(input){const pos=input.selectionStart;lexQuery=input.value;lexPage=1;render();const field=document.getElementById('lex-search');field.focus();field.setSelectionRange(pos,pos)}
function lexFilter(type,value){if(type==='register')lexRegister=value;if(type==='sub')lexSub=value;if(type==='saved')lexOnlySaved=value;lexPage=1;renderLexFilters()}
function lexReset(){resetLexFilters();render()}
function lexAudio(x,example=false){const text=example?x.example:x.it;return `<button class="btn s lex-audio" ${aud()?'':'disabled'} aria-label="${example?'Ouvir exemplo de':'Ouvir'} ${esc(x.it)}" data-text="${esc(text)}" onclick="say(this.dataset.text)">${icon('sound')} ${example?'Exemplo':'Ouvir'}</button>`}
function lexEntry(x){const pair=x.pair?VOCABULARY[course].find(y=>y.pair===x.pair&&y.category!==x.category):null;return `<article class="lex-entry" data-key="${x.k}"><div class="lex-entry-main"><div><div class="lex-labels"><span>${esc(x.sub)}</span><span class="register ${x.register}">${esc(x.register)}</span>${x.region&&x.region!=='Uso geral'&&x.category!=='course'?`<span class="lex-region">${esc(x.region)}</span>`:''}</div><h3 lang="${language().voice}">${esc(x.it)}</h3><p class="lex-translation">${esc(x.pt)}</p></div><div class="lex-actions"><button class="btn s square ${S.fav[x.k]?'gold':''}" aria-label="Salvar ${esc(x.it)}" aria-pressed="${!!S.fav[x.k]}" onclick="tg('${x.k}')">${icon('star')}</button>${lexAudio(x)}</div></div>${x.example?`<div class="lex-example"><p lang="${language().voice}">${esc(x.example)}</p><span>${esc(x.examplePt)}</span>${lexAudio(x,true)}</div>`:''}${['slang','falsefriends'].includes(x.category)?`<p class="lex-usage">${icon('idea')} ${esc(x.note)}</p>`:''}${x.forms||x.note&&!['slang','falsefriends'].includes(x.category)||pair?`<details class="lex-notes"><summary>${pair?'Comparar formal e informal':x.forms?'Formas e uso':'Contexto de uso'}</summary>${x.forms?`<p class="lex-forms" lang="${language().voice}">${esc(x.forms)}</p>`:''}${x.note&&!['slang','falsefriends'].includes(x.category)?`<p>${esc(x.note)}</p>`:''}${pair?`<div class="lex-comparison"><span class="eyebrow">${esc(pair.register)}</span><p lang="${language().voice}">${esc(pair.it)}</p><small>${esc(pair.pt)}</small></div>`:''}</details>`:''}</article>`}
vocab=function(){const sections=lexSections(),all=lexItems(),overview=lexCategory==='overview'&&!lexQuery.trim()&&lexRegister==='all'&&!lexOnlySaved&&lexSub==='all',matching=lexMatches(all),countBy=id=>all.filter(x=>x.category===id).length,section=sections.find(x=>x.id===lexCategory),subs=[...new Set(all.filter(x=>lexCategory==='overview'||lexCategory==='all'||x.category===lexCategory).map(x=>x.sub))];
 return heading('UM IDIOMA PARA USAR','Vocabulário por assunto','Encontre a palavra, entenda o contexto e experimente uma frase completa.',badge(all.length+' entradas'))+`<div class="lex-toolbar"><label class="search" for="lex-search">${icon('search')}<input id="lex-search" type="search" placeholder="Buscar em ${language().target}, português ou nos exemplos" value="${esc(lexQuery)}" oninput="lexSearch(this)"></label><button class="filter-shortcut" onclick="toggleLexFilters()">${icon('book')} Filtrar <span>${lexActiveCount()||'Todos'}</span></button></div>${!aud()?`<div class="lex-audio-notice">${icon('sound')} <p>${S.p.snd?'A leitura depende de uma voz de '+language().target+' disponível no navegador.':'O áudio está desativado nas suas preferências.'} <a href="#/perfil">Ver preferências</a></p></div>`:''}${lexFilterPanel(all,matching)}<div class="lex-content">${overview?`<div class="lex-intro"><h2>Escolha o que você quer aprender.</h2><p class="mu">Verbos, expressões e palavras separados por situação. As gírias indicam contexto; formal e informal têm comparação lado a lado.</p></div><div class="lex-topic-grid">${sections.map((s,i)=>`<button class="card lex-topic-card" onclick="chooseLexTopic('${s.id}')"><div class="row"><span class="eyebrow">${String(i+1).padStart(2,'0')}</span>${badge(countBy(s.id)+' entradas')}</div><h2>${esc(s.title)}</h2><p class="mu">${esc(s.description)}</p><span class="lex-card-link">Explorar tópico ${icon('arrow')}</span></button>`).join('')}</div>`:`<div class="lex-results-heading"><div><p class="eyebrow">${matching.length} RESULTADOS · ${language().name.toUpperCase()}</p><h2>${esc(section?.title||'Resultados por tópico')}</h2><p class="mu">${esc(section?.description||'A busca mantém os resultados agrupados por assunto.')}</p></div><div class="lex-result-actions"><button class="btn s" ${matching.length?'':'disabled'} onclick="practiceLexSelection()">Praticar seleção</button><button class="text-btn" onclick="lexReset()">Limpar filtros</button></div></div>${lexResultGroups(matching)}${matching.length>LEX_PAGE_SIZE?`<div class="lex-pagination"><button class="btn s" ${lexPage<=1?'disabled':''} onclick="lexGoPage(${lexPage-1})">Anterior</button><span>${Math.min(lexPage,Math.ceil(matching.length/LEX_PAGE_SIZE))} / ${Math.ceil(matching.length/LEX_PAGE_SIZE)}</span><button class="btn s" ${lexPage>=Math.ceil(matching.length/LEX_PAGE_SIZE)?'disabled':''} onclick="lexGoPage(${lexPage+1})">Próxima</button></div>`:''}`}</div>`;
};
function lexResultGroups(results){if(!results.length)return '<div class="card empty compact"><h2>Nenhuma entrada encontrada.</h2><p class="mu">Tente outra palavra, outro registro ou limpe os filtros.</p><button class="btn s" onclick="lexReset()">Limpar filtros</button></div>';const page=results.slice((lexPage-1)*LEX_PAGE_SIZE,lexPage*LEX_PAGE_SIZE),groups=new Map();for(const x of page){const title=lexSections().find(s=>s.id===x.category).title+(['verbs','daily','phrases','course'].includes(x.category)?' · '+x.sub:'');if(!groups.has(title))groups.set(title,[]);groups.get(title).push(x)}return [...groups].map(([name,entries])=>`<section class="lex-result-group"><h3 class="lex-group-title">${esc(name)}</h3>${entries.map(lexEntry).join('')}</section>`).join('')}
function lexGoPage(page){lexPage=Math.max(1,page);render();document.querySelector('.lex-results-heading')?.scrollIntoView({block:'start',behavior:'smooth'})}
function practiceLexSelection(){const pool=lexMatches(lexItems());if(!pool.length)return;stopSpeech();stopAudio();const words=shuf(pool).slice(0,8),ex=words.map((x,i)=>{const item={...x,alt:x.category==='verbs'&&course==='en'&&x.it.startsWith('to ')?[x.it.slice(3)]:x.alt||[]};return mkEx(item,['choice','type','order','cloze'][i%4])});S.sess={lk:'rev',ex,i:0,ok:0,intro:1,sec:0,t:Date.now()};st={};save();location.hash='#/lic';render()}

// ---- Visual course picker and vocabulary filters ----
function courseFlag(lang){return `<span class="course-flag ${lang}" aria-hidden="true">${lang==='en'?`<svg viewBox="0 0 60 40" focusable="false"><path fill="#fff" d="M0 0h60v40H0z"/><path stroke="#d74a53" stroke-width="3.08" d="M0 1.54h60M0 7.69h60M0 13.85h60M0 20h60M0 26.15h60M0 32.31h60M0 38.46h60"/><path fill="#304776" d="M0 0h25v21.54H0z"/><path fill="#fff" d="${Array.from({length:9},(_,r)=>Array.from({length:r%2?5:6},(_,c)=>{const x=2.1+c*4.15+(r%2?2.07:0),y=1.9+r*2.2;return `M${x} ${y-0.85}l.25.6.65.02-.5.42.17.63-.57-.34-.55.34.16-.63-.5-.42.65-.02z`}).join('')).join('')}"/></svg>`:'<svg viewBox="0 0 60 40" focusable="false"><path fill="#fff" d="M0 0h60v40H0z"/><path fill="#22a36b" d="M0 0h20v40H0z"/><path fill="#ed5d64" d="M40 0h20v40H40z"/></svg>'}</span>`}
function coursePicker(placement='sidebar'){return `<details class="course-picker ${placement}" id="course-picker-${placement}"><summary aria-label="Trocar curso. Atual: ${language().name}">${courseFlag(course)}<span class="course-current"><small>ESTOU APRENDENDO</small><b>${language().name}</b></span><span class="course-chevron" aria-hidden="true">⌄</span></summary><div class="course-popover"><p class="eyebrow">MEUS CURSOS</p>${['it','en'].map(lang=>`<button class="course-option ${course===lang?'selected':''}" aria-pressed="${course===lang}" onclick="selectCourse('${lang}')">${courseFlag(lang)}<span><b>${LANGUAGE[lang].name}</b><small>${lang==='it'?'Ciao, come stai?':'Hello, how are you?'}</small></span><span class="course-check" aria-hidden="true">${course===lang?'✓':'→'}</span></button>`).join('')}<p class="course-footer">Seu progresso é salvo por idioma.</p></div></details>`}
function closeCoursePickers(restore=false){document.querySelectorAll('.course-picker[open]').forEach(el=>{el.open=false;if(restore)el.querySelector('summary').focus()})}
async function selectCourse(lang){closeCoursePickers();await changeCourse(lang)}
document.addEventListener('click',event=>{if(!event.target.closest('.course-picker'))closeCoursePickers()});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeCoursePickers(true)});
addEventListener('hashchange',()=>closeCoursePickers());
let lexFiltersOpen=false;
function lexActiveCount(){return Number(!['overview','all'].includes(lexCategory))+Number(lexRegister!=='all')+Number(lexSub!=='all')+Number(lexOnlySaved)}
function toggleLexFilters(){const panel=document.getElementById('lex-filter-panel');if(panel){panel.open=!panel.open;lexFiltersOpen=panel.open;if(panel.open)panel.querySelector('summary').focus()}}
function lexChip(label,active,handler,count){return `<button class="filter-chip ${active?'selected':''}" aria-pressed="${active}" data-filter-key="${esc(handler)}" onclick="${handler}"><span>${esc(label)}</span>${count!==undefined?`<small>${count}</small>`:''}</button>`}
function lexFilterPanel(all,matching){const sections=lexSections(),base=all.filter(x=>['overview','all'].includes(lexCategory)||x.category===lexCategory),subs=[...new Set(base.map(x=>x.sub))];return `<details id="lex-filter-panel" class="lex-filter-panel" ${lexFiltersOpen?'open':''} ontoggle="if(this.isConnected)lexFiltersOpen=this.open"><summary><span class="filter-heading"><span class="filter-symbol" aria-hidden="true">☷</span><span><b>Explore do seu jeito</b><small>Tópicos, unidades e estilo de conversa</small></span></span><span class="filter-summary">${lexActiveCount()?lexActiveCount()+' ativos':'Todos os conteúdos'} <span aria-hidden="true">⌄</span></span></summary><div class="filter-body"><fieldset><legend>01 <span>O que você quer estudar?</span></legend><div class="filter-topic-grid">${lexChip('Todos os tópicos',['overview','all'].includes(lexCategory),"chooseLexTopic('all')",all.length)}${sections.map(t=>lexChip(t.title,lexCategory===t.id,`chooseLexTopic('${t.id}')`,all.filter(x=>x.category===t.id).length)).join('')}</div></fieldset>${!['overview','all'].includes(lexCategory)&&subs.length>1?`<fieldset><legend>02 <span>${lexCategory==='course'?'Escolha a unidade':'Dentro deste tópico'}</span></legend><div class="filter-chip-list">${lexChip('Todos os assuntos',lexSub==='all',"lexFilter('sub','all')")}${subs.map((sub,i)=>lexChip(sub,lexSub===sub,`lexPickSub(${i})`,base.filter(x=>x.sub===sub).length)).join('')}</div></fieldset>`:''}<div class="filter-secondary"><fieldset><legend>ESTILO DE LINGUAGEM</legend><div class="filter-chip-list">${[['all','Todos'],['neutro','Neutro'],['formal','Formal'],['informal','Informal'],['coloquial','Gírias']].map(([v,t])=>lexChip(t,lexRegister===v,`lexFilter('register','${v}')`)).join('')}</div></fieldset><fieldset><legend>SUA COLEÇÃO</legend><button data-filter-key="saved" class="filter-saved ${lexOnlySaved?'selected':''}" aria-pressed="${lexOnlySaved}" onclick="lexFilter('saved',${!lexOnlySaved})">${icon('star')} Só favoritos <span>${lexOnlySaved?'✓':'+'}</span></button></fieldset></div></div></details><div class="filter-status" role="status"><span><b>${matching.length}</b> entradas${lexActiveCount()?' com os filtros selecionados':' disponíveis'}</span>${lexActiveCount()||lexQuery?'<button class="text-btn" onclick="lexReset()">Limpar tudo ×</button>':'<span class="tiny">Italiano e inglês para a vida real</span>'}</div>`}
function renderLexFilters(){const key=document.activeElement?.dataset?.filterKey;render();if(key)[...document.querySelectorAll('[data-filter-key]')].find(el=>el.dataset.filterKey===key)?.focus()}
function lexPickSub(index){const subs=[...new Set(lexItems().filter(x=>['overview','all'].includes(lexCategory)||x.category===lexCategory).map(x=>x.sub))];if(subs[index]!==undefined)lexFilter('sub',subs[index])}

// ---- Repeated lesson practice and optional reinforcement ----
const STAGE_NAMES={discover:'1 · Conhecer',practice:'2 · Praticar com ajuda',recall:'3 · Lembrar sem olhar',use:'Usar na conversa',listen:'Ouvir e montar',retry:'Retomar uma dificuldade'};
function guidedExpression(word,kind='order'){
 if(word.it.split(' ').length>1)return mkEx(word,kind);
 const e=mkEx(word,'choice');e.q='Como dizer “'+word.pt+'” em '+language().target+'?';e.a=word.it;e.o=opts(word,'it');e.alt=word.alt||[];return e;
}
const originalSpacedUpdate=upd;
upd=function(key,ok){
 const s=S.sess,now=Date.now();
 if(!s?.lessonMode){originalSpacedUpdate(key,ok);S.srs[key].reviewedAt=now;return}
 s.srsSeen=s.srsSeen||[];
 const alreadyToday=S.srs[key]?.reviewedAt!==undefined&&now-S.srs[key].reviewedAt<DAY;
 if(!ok||!s.srsSeen.includes(key)&&!alreadyToday){originalSpacedUpdate(key,ok);S.srs[key].reviewedAt=now}
 if(!s.srsSeen.includes(key))s.srsSeen.push(key);
};
function scheduleLessonRetry(s,e,ok){
 if(s.builderKey){scheduleBuilderRetry(s,e,ok);return}if(!s.lessonMode||s.pl)return;
 s.missedKeys=s.missedKeys||[];
 if(ok){if(['recall','retry'].includes(e.stage))s.missedKeys=s.missedKeys.filter(k=>k!==e.k);return}
 if(!s.missedKeys.includes(e.k))s.missedKeys.push(e.k);
 if(s.ex.length>=32||s.ex.filter(x=>x.stage==='retry'&&x.k===e.k).length>=2)return;
 let retry;
 if(['dialogue','context'].includes(e.t)){retry=structuredClone(e);retry.o=shuf(retry.o)}
 else {const word=VK[e.k];if(!word)return;retry=e.t==='type'?guidedExpression(word):mkEx(word,'type')}
 retry.stage='retry';retry.context=e.context;retry.why=e.why;
 s.ex.splice(Math.min(s.i+4,s.ex.length),0,retry);
}
function practiceMore(key){
 if(transitionBusy){notice('Aguarde a troca de idioma terminar.');return}
 const lesson=U.flatMap(u=>u.l).find(l=>l.k===key);if(!lesson)return;
 if(S.sess){location.hash='#/lic';render();notice('Retome ou encerre a sessão atual antes de começar outra.');return}
 stopSpeech();stopAudio();S.sess={lk:'rev',lessonKey:key,lessonMode:'extra',missedKeys:[],srsSeen:[],ex:lessonExercises(lesson,true),i:0,ok:0,intro:1,sec:0,t:Date.now()};st={};save();location.hash='#/lic';render();
}
const originalFinishScreen=fim;
fim=function(){
 const last=S.last,key=last?.lessonKey||last?.lk,lesson=U.flatMap(u=>u.l).find(l=>l.k===key);
 if(!last||last.pl||!lesson)return originalFinishScreen();
 const list=U.flatMap(u=>u.l),current=list.findIndex(l=>l.k===key),next=list.slice(current+1).find(l=>!S.done[l.k]),missed=(last.missedKeys||[]).filter(k=>VK[k]),needsPractice=missed.length>0||last.ok/last.n<.8;
 return `<section class="card hero practice-finish"><p class="eyebrow">${last.lessonMode==='extra'?'PRÁTICA EXTRA':'ETAPA CONCLUÍDA'} · ${esc(lesson.t)}</p><h1>${needsPractice?'Vamos fixar um pouco mais?':'Você deu mais um passo.'}</h1><p>${last.ok}/${last.n} acertos · +${last.xp} XP · ${Math.max(1,Math.round(last.sec/60))} min</p><p class="mu">${needsPractice?'Uma nova rodada ajuda a retomar os pontos que ainda confundem.':'Você pode continuar ou praticar esta etapa de novo, no seu ritmo.'} Volte também em outro dia para lembrar sem a resposta fresca na cabeça.</p></section>${missed.length?`<section class="card practice-points"><p class="eyebrow">PONTOS PARA RETOMAR</p>${missed.map(k=>`<p><b lang="${language().voice}">${esc(VK[k].it)}</b> <span class="mu">— ${esc(VK[k].pt)}</span></p>`).join('')}</section>`:''}<div class="practice-finish-actions"><button class="btn w" onclick="practiceMore('${lesson.k}')">${icon('rev')} Praticar mais: ${esc(lesson.t)}</button>${next?`<button class="btn s w" onclick="startLesson('${next.k}')">Continuar: ${esc(next.t)} ${icon('arrow')}</button>`:'<a class="btn s w" href="#/trilha">Voltar à trilha</a>'}<a class="text-btn" href="#/rev">Ver revisões agendadas</a></div>`;
};
const repeatedPracticeRender=render;
render=function(){repeatedPracticeRender();if(!authReady||(!account&&!guest)||!S.p.on)return;
 const route=(location.hash.slice(2)||'').split('?')[0],a=document.getElementById('app'),s=S.sess;
 if(route==='lic'&&s?.lessonMode){
  const lesson=U.flatMap(u=>u.l).find(l=>l.k===s.lessonKey);
  if(!s.intro){a.querySelector('.lesson-intro>section:first-child>p:not(.eyebrow)')?.replaceChildren(document.createTextNode('Conheça, pratique e lembre: cada expressão aparece em três rodadas antes de continuar.'));a.querySelector('.lesson-intro>section:first-child')?.insertAdjacentHTML('beforeend','<div class="practice-roadmap"><span>01 Conhecer</span><span>02 Praticar</span><span>03 Lembrar</span><small>Depois, use na conversa. Os erros ganham reforço.</small></div>')}
  else {const e=s.ex[s.i];a.querySelector('.exercise')?.insertAdjacentHTML('afterbegin',`<div class="practice-stage" role="status"><span>${esc(s.lessonMode==='extra'?'PRÁTICA EXTRA · '+(lesson?.t||''):lesson?.t||'')}</span><b>${esc(STAGE_NAMES[e.stage]||'Prática')}</b><small>${e.stage==='retry'?'Esta expressão voltou para você tentar de novo.':e.stage==='recall'?'Tente lembrar antes de conferir. Você já praticou esta expressão.':e.stage==='practice'?'Agora use a expressão de outra forma.':'Um passo de cada vez, sem pressa de avançar.'}</small></div>`)}
 }
 if(route==='trilha')a.querySelectorAll('.lc:not(.rv)').forEach(button=>{const match=button.getAttribute('onclick')?.match(/startLesson\('([0-9]+-[0-2])'\)/);if(match&&S.done[match[1]]){const repeat=document.createElement('button');repeat.className='text-btn trail-extra';repeat.textContent='↻ Praticar mais esta etapa';repeat.setAttribute('onclick',`practiceMore('${match[1]}')`);button.insertAdjacentElement('afterend',repeat)}});
};

const SENTENCE_LESSONS={"it":[{"id":"identity","title":"Apresentar-se","topic":"identity","rule":"Essere muda com a pessoa: io sono, tu sei, lui/lei è, noi siamo. O pronome pode ser omitido. Para dizer o nome, use Mi chiamo… . Aqui vamos montar o modelo mostrado com as peças disponíveis.","parts":["Io = eu","sono = sou","brasiliano = brasileiro"],"example":"Io sono brasiliano","meaning":"Sou brasileiro","rows":[{"text":"Io sono uno studente","pt":"Sou estudante"},{"text":"Tu sei mio amico","pt":"Você é meu amigo"},{"text":"Mi chiamo Anna","pt":"Eu me chamo Anna"},{"text":"Lei è brasiliana","pt":"Ela é brasileira"},{"text":"Noi siamo studenti","pt":"Somos estudantes"},{"text":"Lui è mio fratello","pt":"Ele é meu irmão"}]},{"id":"states","title":"Dizer como você está","topic":"states","rule":"Fome, sede e sono usam avere: ho fame, ho sete, ho sonno. Para emoções ou cansaço, use essere: sono felice, sono stanco. O gênero muda: stanco/stanca.","parts":["Io = eu (opcional)","ho = tenho","fame = fome"],"example":"Io ho fame","meaning":"Estou com fome","rows":[{"text":"Io ho sete","pt":"Estou com sede"},{"text":"Lei è stanca","pt":"Ela está cansada"},{"text":"Noi siamo a casa","pt":"Estamos em casa"},{"text":"Io ho sonno","pt":"Estou com sono"},{"text":"Lui è felice","pt":"Ele está feliz"},{"text":"Tu hai fame","pt":"Você está com fome"}]},{"id":"routine","title":"Contar sua rotina","topic":"routine","rule":"O verbo informa a pessoa. No presente: parlo/parli/parla; lavoro/lavori/lavora. Não acrescente sono antes de studio para falar de um hábito. Use ogni giorno para “todos os dias”.","parts":["Io = eu","lavoro = trabalho","ogni giorno = todos os dias"],"example":"Io lavoro ogni giorno","meaning":"Trabalho todos os dias","rows":[{"text":"Io studio italiano","pt":"Estudo italiano"},{"text":"Lei lavora a casa","pt":"Ela trabalha em casa"},{"text":"Noi studiamo ogni giorno","pt":"Estudamos todos os dias"},{"text":"Lui parla inglese","pt":"Ele fala inglês"},{"text":"Loro abitano in Brasile","pt":"Eles moram no Brasil"},{"text":"Io lavoro la mattina","pt":"Trabalho de manhã"}]},{"id":"negative","title":"Montar frases negativas","topic":"present","rule":"Para negar, coloque non imediatamente antes do verbo: io non parlo. A ordem continua com o sujeito antes de non, quando ele aparece. Non ho fame significa “não estou com fome”.","parts":["Io = eu","non = não","lavoro qui = trabalho aqui"],"example":"Io non lavoro qui","meaning":"Não trabalho aqui","rows":[{"text":"Io non parlo inglese","pt":"Não falo inglês"},{"text":"Lei non lavora qui","pt":"Ela não trabalha aqui"},{"text":"Noi non siamo stanchi","pt":"Não estamos cansados"},{"text":"Lui non studia italiano","pt":"Ele não estuda italiano"},{"text":"Loro non abitano qui","pt":"Eles não moram aqui"},{"text":"Io non ho fame","pt":"Não estou com fome"}]},{"id":"questions","title":"Fazer perguntas","topic":"identity","rule":"O italiano não precisa de um auxiliar como do para perguntar. Dove, come e quando introduzem a pergunta. Em È aperto il negozio?, o verbo pode vir antes do sujeito. Preste atenção à pontuação das peças.","parts":["Dove = onde","abiti? = você mora?"],"example":"Dove abiti?","meaning":"Onde você mora?","rows":[{"text":"Tu parli inglese?","pt":"Você fala inglês?"},{"text":"Dove lavora Anna?","pt":"Onde Anna trabalha?"},{"text":"Come ti chiami?","pt":"Como você se chama?"},{"text":"Quando parte il treno?","pt":"Quando o trem parte?"},{"text":"Quanto costa questo libro?","pt":"Quanto custa este livro?"},{"text":"È aperto il negozio?","pt":"A loja está aberta?"}]},{"id":"requests","title":"Fazer pedidos educados","topic":"requests","rule":"Vorrei significa “eu gostaria” e pode vir antes do que você quer. Potrebbe + infinitivo é um pedido formal; potrebbe ripetere significa “o senhor/a senhora poderia repetir?”. Per favore suaviza o pedido.","parts":["Vorrei = eu gostaria de","un biglietto = uma passagem"],"example":"Vorrei un biglietto","meaning":"Eu gostaria de uma passagem","rows":[{"text":"Vorrei un tavolo per due","pt":"Eu gostaria de uma mesa para dois"},{"text":"Potrebbe aiutarmi per favore?","pt":"O senhor poderia me ajudar por favor?"},{"text":"Vorrei il menu","pt":"Eu gostaria do cardápio"},{"text":"Potrebbe parlare lentamente?","pt":"O senhor poderia falar devagar?"},{"text":"Vorrei un bicchiere di acqua","pt":"Eu gostaria de um copo de água"},{"text":"Potrebbe ripetere per favore?","pt":"O senhor poderia repetir por favor?"}]},{"id":"location","title":"Dizer onde algo está","topic":"directions","rule":"Use essere + lugar: è vicino alla… = fica perto da… . Preposições podem se juntar ao artigo: a + la = alla, in + la = nella, su + il = sul. A casa dispensa artigo.","parts":["La stazione = a estação","è = fica","vicino al museo = perto do museu"],"example":"La stazione è vicino al museo","meaning":"A estação fica perto do museu","rows":[{"text":"La banca è vicino al museo","pt":"O banco fica perto do museu"},{"text":"Noi siamo alla stazione","pt":"Estamos na estação"},{"text":"Le chiavi sono nella borsa","pt":"As chaves estão na bolsa"},{"text":"Il ristorante è vicino alla banca","pt":"O restaurante fica perto do banco"},{"text":"Io sono a casa","pt":"Estou em casa"},{"text":"Il libro è sul tavolo","pt":"O livro está sobre a mesa"}]},{"id":"plans","title":"Falar dos seus planos","topic":"plans","rule":"O presente com uma indicação de tempo pode expressar um plano futuro: domani studio. Aqui vamos usar o tempo no começo, seguido do verbo e dos complementos. É uma forma comum de falar de planos próximos.","parts":["Domani = amanhã","studio = estudo / vou estudar","italiano = italiano"],"example":"Domani studio italiano","meaning":"Amanhã vou estudar italiano","rows":[{"text":"Domani parto per Roma","pt":"Amanhã parto para Roma"},{"text":"Domani studio inglese","pt":"Amanhã vou estudar inglês"},{"text":"Stasera mangiamo a casa","pt":"Hoje à noite vamos comer em casa"},{"text":"Domani lavoro a casa","pt":"Amanhã vou trabalhar em casa"},{"text":"Sabato visitiamo il museo","pt":"Sábado vamos visitar o museu"},{"text":"Domani ti chiamo","pt":"Amanhã vou ligar para você"}]}],"en":[{"id":"identity","title":"Apresentar-se","topic":"identity","rule":"Para dizer quem você é, use sujeito + am/is/are + informação. Com I, use am; com you, are. Para o nome, também é natural dizer My name is… .","parts":["I = eu","am = sou","Brazilian = brasileiro(a)"],"example":"I am Brazilian","meaning":"Sou brasileiro(a)","rows":[{"text":"I am a student","pt":"Sou estudante"},{"text":"You are my friend","pt":"Você é meu amigo"},{"text":"My name is Ana","pt":"Meu nome é Ana"},{"text":"She is Brazilian","pt":"Ela é brasileira"},{"text":"We are students","pt":"Somos estudantes"},{"text":"He is my brother","pt":"Ele é meu irmão"}]},{"id":"states","title":"Dizer como você está","topic":"states","rule":"Em inglês, fome, sede e frio usam to be: I am hungry/thirsty/cold. Não traduza literalmente “tenho fome” como I have hungry. Com she/he, use is.","parts":["I = eu","am = estou","hungry = com fome"],"example":"I am hungry","meaning":"Estou com fome","rows":[{"text":"I am tired","pt":"Estou cansado"},{"text":"She is thirsty","pt":"Ela está com sede"},{"text":"We are at home","pt":"Estamos em casa"},{"text":"I am cold","pt":"Estou com frio"},{"text":"He is happy","pt":"Ele está feliz"},{"text":"You are hungry","pt":"Você está com fome"}]},{"id":"routine","title":"Contar sua rotina","topic":"routine","rule":"Use sujeito + verbo + complemento. No presente afirmativo, he/she/it normalmente acrescentam -s ao verbo: work → works, study → studies. I work dispensa am.","parts":["I = eu","work = trabalho","every day = todos os dias"],"example":"I work every day","meaning":"Trabalho todos os dias","rows":[{"text":"I study English","pt":"Estudo inglês"},{"text":"She works at home","pt":"Ela trabalha em casa"},{"text":"We study every day","pt":"Estudamos todos os dias"},{"text":"He speaks Italian","pt":"Ele fala italiano"},{"text":"They live in Brazil","pt":"Eles moram no Brasil"},{"text":"I work in the morning","pt":"Trabalho de manhã"}]},{"id":"negative","title":"Montar frases negativas","topic":"present","rule":"Com verbos comuns, use do not ou does not + verbo base. Com she, use does not work, sem -s em work. Com to be, coloque not depois de am/is/are. Aqui usaremos as formas completas.","parts":["I = eu","do not = não","work here = trabalho aqui"],"example":"I do not work here","meaning":"Não trabalho aqui","rows":[{"text":"I do not speak Italian","pt":"Não falo italiano"},{"text":"She does not work here","pt":"Ela não trabalha aqui"},{"text":"We are not tired","pt":"Não estamos cansados"},{"text":"He does not study English","pt":"Ele não estuda inglês"},{"text":"They do not live here","pt":"Eles não moram aqui"},{"text":"I am not hungry","pt":"Não estou com fome"}]},{"id":"questions","title":"Fazer perguntas","topic":"identity","rule":"Com to be, inverta verbo e sujeito: You are… → Are you…? Com verbos comuns, use Do/Does + sujeito + verbo base. Where e what vêm antes dessa estrutura.","parts":["Do = auxiliar","you = você","speak English? = fala inglês?"],"example":"Do you speak English?","meaning":"Você fala inglês?","rows":[{"text":"Are you a student?","pt":"Você é estudante?"},{"text":"Where do you live?","pt":"Onde você mora?"},{"text":"Does she work here?","pt":"Ela trabalha aqui?"},{"text":"What is your name?","pt":"Qual é o seu nome?"},{"text":"Do they speak Italian?","pt":"Eles falam italiano?"},{"text":"Are we late?","pt":"Estamos atrasados?"}]},{"id":"requests","title":"Fazer pedidos educados","topic":"requests","rule":"I would like + objeto é uma forma educada de pedir. Para pedir uma ação, use Could you + verbo base…? Please pode ficar no fim. Would like significa “gostaria”, não “gosto”.","parts":["I = eu","would like = gostaria de","some water = um pouco de água"],"example":"I would like some water","meaning":"Eu gostaria de um pouco de água","rows":[{"text":"I would like a ticket","pt":"Eu gostaria de uma passagem"},{"text":"Could you help me?","pt":"Você poderia me ajudar?"},{"text":"I would like the menu","pt":"Eu gostaria do cardápio"},{"text":"Could you speak slowly?","pt":"Você poderia falar devagar?"},{"text":"I would like a table for two","pt":"Eu gostaria de uma mesa para dois"},{"text":"Could you repeat that please?","pt":"Você poderia repetir isso por favor?"}]},{"id":"location","title":"Dizer onde algo está","topic":"directions","rule":"Para localizar, use sujeito + is/are + expressão de lugar. Next to = ao lado de; near = perto de; in = dentro de/em. The acompanha o lugar específico.","parts":["The station = a estação","is = fica","near the hotel = perto do hotel"],"example":"The station is near the hotel","meaning":"A estação fica perto do hotel","rows":[{"text":"The bank is next to the hotel","pt":"O banco fica ao lado do hotel"},{"text":"We are at the station","pt":"Estamos na estação"},{"text":"The keys are in the bag","pt":"As chaves estão na bolsa"},{"text":"The restaurant is near the bank","pt":"O restaurante fica perto do banco"},{"text":"I am at home","pt":"Estou em casa"},{"text":"The book is on the table","pt":"O livro está sobre a mesa"}]},{"id":"plans","title":"Falar dos seus planos","topic":"plans","rule":"Para uma intenção futura, use am/is/are + going to + verbo base. Não esqueça to. Tomorrow pode ficar no final; no modelo, vamos usar essa ordem.","parts":["I am = sujeito + forma de be","going to = marca de intenção","study tomorrow = estudar amanhã"],"example":"I am going to study tomorrow","meaning":"Vou estudar amanhã","rows":[{"text":"I am going to travel tomorrow","pt":"Vou viajar amanhã"},{"text":"She is going to study English","pt":"Ela vai estudar inglês"},{"text":"We are going to meet tomorrow","pt":"Vamos nos encontrar amanhã"},{"text":"He is going to work at home","pt":"Ele vai trabalhar em casa"},{"text":"They are going to visit Rome","pt":"Eles vão visitar Roma"},{"text":"I am going to call you tomorrow","pt":"Vou ligar para você amanhã"}]}]};

function dialogueMeaningExercise(l){const last=l.dialogue.at(-1);return {t:'context',k:l.w[0].k,topic:l.topic,q:'Qual é o sentido da última fala da conversa?',a:last.pt,o:shuf([last.pt,...l.dialogue.slice(0,-1).map(x=>x.pt)].filter((x,i,a)=>a.indexOf(x)===i)),ctx:l.dialogue,context:l.goal,why:'A última fala é “'+last.text+'”: '+last.pt+'. '+l.task.why,alt:[]}}
const builderLesson=key=>SENTENCE_LESSONS[course].find(b=>b.id===key);
function sentenceLibrary(){return heading('DO EXEMPLO À SUA PRÓPRIA FRASE','Montar frases','Entenda a estrutura, pratique com ajuda e tente montar sem olhar o modelo.',badge(language().name))+`<section class="card builder-welcome"><h2>Você aprende montando.</h2><p class="mu">Cada oficina tem uma explicação e seis frases. Nas primeiras, começamos juntos; depois você recebe pistas e, por fim, monta por conta própria. Toque nas peças para mover e desfazer.</p><div class="builder-path"><span>01 Entenda</span><span>02 Monte com ajuda</span><span>03 Tente sozinho</span></div></section><div class="builder-grid">${SENTENCE_LESSONS[course].map((b,i)=>{const progress=S.learning?.builders?.[b.id];return `<article class="card builder-card"><div class="row"><span class="eyebrow">OFICINA ${String(i+1).padStart(2,'0')}</span>${badge(progress?'Praticada '+progress.completed+'×':'6 frases')}</div><h2>${esc(b.title)}</h2><p class="mu">${esc(b.rule)}</p><blockquote lang="${language().voice}">${esc(b.example)}</blockquote><button class="btn s" onclick="startBuilder('${b.id}')">${S.sess?.builderKey===b.id?'Retomar':'Aprender montando'} ${icon('arrow')}</button></article>`}).join('')}</div>`}
function startBuilder(key){
 if(transitionBusy){notice('Aguarde a troca de idioma terminar.');return}
 const lesson=builderLesson(key);if(!lesson)return;
 if(S.sess){location.hash='#/lic';render();if(S.sess.builderKey!==key)notice('Retome a sessão atual antes de iniciar outra.');return}
 stopSpeech();stopAudio();const anchor=V.find(x=>x.topic===lesson.topic)?.k||'0-0-0';
 const ex=lesson.rows.map((row,i)=>{let bank=shuf(row.text.split(' '));if(bank.join(' ')===row.text)bank.push(bank.shift());return {t:'order',k:anchor,q:'Monte: “'+row.pt+'”',a:row.text,w:bank,topic:lesson.topic,context:lesson.title,why:lesson.rule,alt:[],buildIndex:i,stage:'practice'}});
 S.sess={lk:'rev',builderKey:key,ex,i:0,ok:0,intro:1,sec:0,t:Date.now()};st={};save();location.hash='#/lic';render();
}
function scheduleBuilderRetry(s,e,ok){if(ok||s.ex.length>=12||s.ex.filter(x=>x.buildIndex===e.buildIndex).length>=2)return;const retry=structuredClone(e);retry.stage='retry';retry.w=shuf(retry.w);s.ex.splice(Math.min(s.i+3,s.ex.length),0,retry)}
function builderModel(lesson){return `<p class="mu">${esc(lesson.rule)}</p><div class="builder-parts">${lesson.parts.map(p=>`<span>${esc(p)}</span>`).join('')}</div><p class="builder-model" lang="${language().voice}">${esc(lesson.example)}</p><p class="tiny">${esc(lesson.meaning)}</p><button class="btn s" ${aud()?'':'disabled'} data-text="${esc(lesson.example)}" onclick="say(this.dataset.text)">${icon('sound')} Ouvir modelo</button>`}
function builderHelp(){const s=S.sess,e=s?.ex[s.i];if(!s?.builderKey||st.res)return;const target=e.a.split(' '),pick=st.pick||[],wrong=pick.findIndex((word,i)=>word!==target[i]);st.builderHelp=wrong>=0?'Confira a peça '+(wrong+1)+' da sua frase. Remova a partir dela e pense na estrutura do modelo.':pick.length>=target.length?'Sua frase está montada. Toque em Verificar.':'A próxima peça é “'+target[pick.length]+'”. Pense na função dela na frase.';render()}
function addBuilderPiece(){const s=S.sess,e=s?.ex[s.i];if(!s?.builderKey||st.res)return;const target=e.a.split(' ');st.pick=st.pick||[];if(st.pick.some((w,i)=>w!==target[i])){builderHelp();return}if(st.pick.length<target.length)st.pick.push(target[st.pick.length]);st.builderHelp='Colocamos uma peça juntos. Agora tente escolher a próxima.';render()}
function builderPanel(){const s=S.sess,e=s.ex[s.i],lesson=builderLesson(s.builderKey),level=e.buildIndex<2?'Com ajuda':e.buildIndex<4?'Com pistas':'Sua vez',guided=e.buildIndex<2||e.stage==='retry';return `<section class="builder-teaching"><div class="row"><p class="eyebrow">${esc(lesson.title)}</p>${badge(e.stage==='retry'?'Vamos retomar':level)}</div><h3>Entenda antes de montar.</h3>${guided?builderModel(lesson):`<details><summary>Rever a explicação e o exemplo</summary>${builderModel(lesson)}</details>`}<p class="tiny">${guided?'Já começamos a frase com uma peça. Continue escolhendo as próximas.':'Agora monte a frase pedida com as peças abaixo. Se precisar, peça uma pista.'} Este exercício segue o modelo ensinado; outras ordens podem ser naturais fora dele.</p></section>`}
const beforeBuilderView=lessonView;
lessonView=function(){const s=S.sess,e=s?.ex[s.i];if(s?.builderKey&&e&&s.intro){
 if(!st.pick){st.pick=s.builderDraft?.i===s.i?[...s.builderDraft.pick]:(e.buildIndex<2||e.stage==='retry'?e.a.split(' ').slice(0,1):[])}
 const draft={i:s.i,pick:[...st.pick]};if(JSON.stringify(s.builderDraft)!==JSON.stringify(draft)){s.builderDraft=draft;save()}
 }return beforeBuilderView()};
const beforeBuilderFinish=fim;
fim=function(){if(!S.last?.builderKey)return beforeBuilderFinish();const b=builderLesson(S.last.builderKey);if(!b)return beforeBuilderFinish();return `<section class="card hero practice-finish"><p class="eyebrow">OFICINA DE FRASES · ${esc(b.title)}</p><h1>${S.last.ok/S.last.n<.8?'Vamos montar juntos mais uma vez?':'Você construiu novas frases.'}</h1><p>${S.last.ok}/${S.last.n} acertos · +${S.last.xp} XP</p><p class="mu">Lembre da estrutura: ${esc(b.rule)}</p></section><div class="practice-finish-actions"><button class="btn" onclick="startBuilder('${b.id}')">Praticar esta estrutura de novo</button><a class="btn s" href="#/frases">Escolher outra oficina</a><a class="text-btn" href="#/trilha">Voltar à trilha</a></div>`};
function playOrderAudio(slow=false){const e=S.sess?.ex[S.sess.i];if(e?.audioText)say(e.audioText,slow)}
const beforeListeningRender=render;
render=function(){beforeListeningRender();if(!authReady||(!account&&!guest)||!S.p.on)return;const a=document.getElementById('app'),route=(location.hash.slice(2)||'').split('?')[0],s=S.sess,e=s?.ex[s.i];
 if(route===''||route==='trilha')a.insertAdjacentHTML('beforeend','<section class="card builder-invite"><div><p class="eyebrow">APRENDA CONSTRUINDO</p><h2>Uma frase, peça por peça.</h2><p class="mu">Explicação, exemplo e ajuda que diminui a cada rodada.</p></div><a class="btn s" href="#/frases">Montar frases →</a></section>');
 if(route===''&&s?.builderKey){const lesson=builderLesson(s.builderKey),hero=a.querySelector('.home-lead .hero');if(lesson&&hero){hero.querySelector('h2').textContent=lesson.title;hero.querySelector('.eyebrow').textContent='OFICINA EM ANDAMENTO';hero.querySelector('p.mu').textContent='Montagem de frases · continue de onde parou.'}}
 if(route==='lic'&&s?.builderKey&&e){const area=a.querySelector('.exercise');area?.insertAdjacentHTML('afterbegin',builderPanel());const h=area?.querySelector('h2');h?.insertAdjacentHTML('afterend',`<div class="builder-tools"><button class="btn s" ${st.res?'disabled':''} onclick="builderHelp()">Quero uma pista</button><button class="text-btn" ${st.res?'disabled':''} onclick="addBuilderPiece()">Colocar uma peça comigo</button><p role="status">${esc(st.builderHelp||'Toque numa peça da sua frase para devolvê-la ao banco.')}</p></div>`);area?.querySelector('.fb .btn[onclick^="tg"]')?.remove()}
 if(route==='lic'&&e?.t==='listen'&&!aud())a.querySelector('.exercise h2')?.insertAdjacentHTML('afterend','<p class="lex-audio-notice">Sem voz compatível: escolha a expressão que significa “'+esc(VK[e.k].pt)+'”.</p>');
 if(route==='lic'&&e?.audioOrder){a.querySelector('.exercise h2')?.insertAdjacentHTML('afterend',`<section class="order-listening"><div class="dialogue-audio"><button class="btn s" ${aud()?'':'disabled'} onclick="playOrderAudio()">${icon('sound')} Ouvir frase</button><button class="btn s" ${aud()?'':'disabled'} onclick="playOrderAudio(true)">Mais devagar</button></div>${aud()?`<details><summary>Preciso de apoio em texto</summary><p>${esc(VK[e.k].pt)}</p><p lang="${language().voice}">${esc(e.audioText)}</p></details>`:`<p class="mu">Sem voz compatível: monte a partir do significado — ${esc(VK[e.k].pt)}.</p>`}</section>`)}
};

boot();
